window.EDAG_QUESTIONS = [{"id":"practice-1-1","chapter":1,"topic":"Pure EC vs pure-play","section":"s2","prompt":"Penjual hanya memiliki situs dan gudang. Pesanan serta pembayaran sepatu dilakukan online, lalu sepatu dikirim kurir. Pasangan klasifikasi paling tepat pada dimensi organisasi dan transaksi adalah…","reason":"Kanal organisasi dan digitasi transaksi adalah dua sumbu berbeda. Tidak adanya toko retail mendukung pure-play pada definisi materi, sedangkan produk yang dikirim fisik membuat transaksi partial EC. Gudang tidak menggugurkan pure-play.","options":["Click-and-mortar; transaksi pure EC","Pure-play; transaksi pure EC","Brick-and-mortar; transaksi partial EC","Pure-play; transaksi partial EC"],"analysis":["Gudang bukan toko retail; pemenuhan fisik juga menggugurkan pure EC.","Menyamakan kanal online dengan digitasi seluruh proses mengabaikan pengiriman.","Aset gudang tidak berarti kanal penjualan berupa toko fisik.","Kanal penjualan online dan pengiriman fisik dapat hadir bersamaan."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-2","chapter":1,"topic":"Relasi transaksi","section":"s3","prompt":"Sebuah marketplace mempertemukan dua mahasiswa yang menjual-beli kalkulator pribadi. Pada hari yang sama, marketplace menjual paket iklan kepada toko alat tulis. Klasifikasi dua transaksi tersebut berturut-turut adalah…","reason":"Pilih unit analisis transaksinya. Penjual dan pembeli kalkulator adalah individu; penjualan layanan iklan berlangsung antara platform bisnis dan toko bisnis. Kehadiran marketplace tidak mengubah identitas pihak pada transaksi kalkulator.","options":["C2C kemudian B2B","B2C kemudian C2B","B2B2C kemudian B2C","C2C kemudian C2B"],"analysis":["Relasi barang antarmahasiswa berbeda dari layanan iklan antarbisnis.","Platform tidak menjadi penjual kalkulator; toko juga bukan konsumen individu.","Tidak ada bukti rantai dua bisnis yang menjual kalkulator dalam kasus.","Pengiklan adalah bisnis, sehingga layanan platform bukan transaksi konsumen-ke-bisnis."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-3","chapter":1,"topic":"Framework EC","section":"s4","prompt":"Tim sudah mempercepat halaman checkout. Namun 12% pesanan yang dibayar dibatalkan karena stok pemasok tidak sinkron. Investasi berikut yang paling langsung menangani mekanisme kegagalan adalah…","reason":"Kegagalan berada pada hubungan order, stok dan pemenuhan. Perbaikan perlu menghubungkan data/proses antarpihak. Promosi atau personalisasi dapat memperbesar permintaan tanpa menambah kemampuan memenuhi pesanan.","options":["Validasi alamat dan penjadwalan kapasitas kurir","Pemeriksaan kredit dan konfirmasi ulang pembeli","Sinkronisasi stok dan reservasi lintas mitra","Rekonsiliasi pembayaran dan percepatan refund"],"analysis":["Menangani kelayakan pengiriman setelah barang tersedia; bukti kasus menunjuk stok pemasok.","Menangani risiko pembayaran atau niat pembeli, sedangkan order telah dibayar dan stok tidak sinkron.","Menyatukan ketersediaan dengan komitmen order menangani penyebab pembatalan.","Mengurangi dampak finansial pembatalan, tetapi barang yang dijanjikan tetap tidak tersedia."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-4","chapter":1,"topic":"Business model canvas","section":"s8","prompt":"Platform buku kampus mengklaim nilai “edisi tepat, ambil hari ini”. Dari empat perubahan berikut, mana yang paling menguji konsistensi antarblok canvas?","reason":"Proposisi nilai tentang edisi dan waktu harus didukung sumber daya data serta aktivitas pemenuhan. Menambah pendapatan atau tampilan tidak membuktikan kemampuan menyampaikan janji. Canvas merupakan hubungan keputusan, bukan daftar fitur.","options":["Validasi klik kanal dan respons kampanye rujukan","Validasi ISBN dan kapasitas titik pengambilan","Validasi minat segmen dan pertumbuhan langganan","Validasi biaya pemasok dan margin setiap kategori"],"analysis":["Menguji akuisisi pelanggan; keberhasilan janji fulfillment memerlukan bukti operasi.","Menguji ketepatan edisi serta kemampuan memenuhi janji waktu melalui aktivitas dan sumber daya.","Menguji permintaan dan penerimaan berulang, belum kemampuan menyediakan edisi tepat hari ini.","Menguji kelayakan biaya, tetapi margin tidak membuktikan ketepatan edisi atau kesiapan pengambilan."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-5","chapter":1,"topic":"Revenue vs value proposition","section":"s9","prompt":"Pelanggan membayar Rp40.000 per bulan untuk akses perbandingan pemasok. Platform juga menerima komisi untuk transaksi yang terjadi melalui rujukannya. Pasangan pernyataan paling tepat adalah…","reason":"Subscription dan referral commission menjelaskan arus pendapatan. Alasan pelanggan mau membayar adalah nilai pencarian/perbandingan yang diperoleh. Model yang sama dapat memiliki beberapa revenue streams sekaligus.","options":["Perbandingan dan subscription adalah customer segments","Affiliate fee dan perbandingan adalah key resources","Subscription dan komisi adalah value propositions","Subscription dan affiliate fee adalah revenue streams"],"analysis":["Keduanya bukan kelompok pelanggan yang dilayani.","Komisi adalah penerimaan; kemampuan perbandingan perlu sumber daya pendukung.","Cara menarik uang berbeda dari manfaat bagi pelanggan.","Keduanya menyebut cara platform menerima imbalan."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-6","chapter":1,"topic":"Reach, richness, affiliation","section":"s5","prompt":"Marketplace sudah memuat satu juta SKU, tetapi deskripsi kompatibilitas sangat minim. Menambah video instalasi dan filter kecocokan terutama memperbaiki…","reason":"Kasus sudah memiliki jangkauan penawaran yang luas. Kekurangannya adalah kedalaman informasi dan dukungan keputusan. Video dan filter terutama meningkatkan richness; efek lain mungkin ada, tetapi bukan pembeda utama.","options":["Richness dalam informasi produk","Reach dalam cakupan penjual","Affiliation dalam struktur kemitraan","Digitization dalam bentuk barang"],"analysis":["Kedalaman dan relevansi informasi membantu menilai kecocokan.","Tidak ada penambahan pihak atau perluasan pasar yang dinyatakan.","Kasus tidak mengubah hubungan atau kerja sama mitra.","Video tidak mengubah produk fisik menjadi barang digital."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-7","chapter":1,"topic":"GMV dan unit economics","section":"s9","prompt":"Marketplace memfasilitasi 100 order, masing-masing Rp200.000. Komisi 5%; biaya variabel platform Rp7.000 per order. Mengabaikan biaya tetap, kontribusi total platform adalah…","reason":"GMV Rp20 juta bukan pendapatan yang seluruhnya menjadi hak platform. Komisi = 5% × Rp20 juta = Rp1 juta. Biaya variabel = 100 × Rp7.000 = Rp700.000; kontribusi Rp300.000 sebelum biaya tetap.","options":["Rp700.000 sebelum biaya tetap","Rp300.000 sebelum biaya tetap","Rp1.000.000 sebelum biaya tetap","Rp19.300.000 sebelum biaya tetap"],"analysis":["Ini total biaya variabel, bukan kontribusi pendapatan.","Pendapatan komisi dikurangi biaya variabel menghasilkan kontribusi ini.","Ini pendapatan komisi sebelum dikurangi biaya variabel.","Ini keliru memperlakukan seluruh GMV sebagai pendapatan platform."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-8","chapter":1,"topic":"EC dan EB","section":"s1","prompt":"Dengan definisi EC sempit dan EB luas yang dinyatakan materi, portal pelatihan internal dapat termasuk EB meskipun tidak memproses penjualan kepada pelanggan.","reason":"EB mencakup proses internal dan pembelajaran, sedangkan EC sempit menitikberatkan pertukaran komersial. Pernyataan menetapkan definisi dengan jelas sehingga tidak bergantung pada penggunaan EC luas di bagian lain.","options":["Benar","Salah"],"analysis":["EB mencakup proses internal dan pembelajaran, sedangkan EC sempit menitikberatkan pertukaran komersial. Pernyataan menetapkan definisi dengan jelas sehingga tidak bergantung pada penggunaan EC luas di bagian lain.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-9","chapter":1,"topic":"Manfaat dan hasil","section":"s5","prompt":"Jika biaya akuisisi per pelanggan naik lebih cepat daripada kontribusi pembeliannya, pertumbuhan order saja belum cukup membuktikan model EC makin menguntungkan.","reason":"Pertumbuhan volume harus dibandingkan dengan biaya dan margin. Order merupakan aktivitas transaksi; laba memerlukan pendapatan yang menutup biaya terkait. Pernyataan tidak menyatakan pertumbuhan selalu buruk, hanya membatasi inferensi.","options":["Benar","Salah"],"analysis":["Pertumbuhan volume harus dibandingkan dengan biaya dan margin. Order merupakan aktivitas transaksi; laba memerlukan pendapatan yang menutup biaya terkait. Pernyataan tidak menyatakan pertumbuhan selalu buruk, hanya membatasi inferensi.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-1-10","chapter":1,"topic":"Jaringan dan aktor","section":"s3","prompt":"Karena perusahaan mengakses katalog pemasok melalui internet publik, transaksi pembelian komponen itu diklasifikasikan B2C, bukan B2B.","reason":"Internet adalah kanal jaringan. Identitas serta tujuan transaksi tetap antarorganisasi, sehingga B2B. Penggunaan jaringan publik tidak mengubah pembeli bisnis menjadi konsumen pribadi.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Internet adalah kanal jaringan. Identitas serta tujuan transaksi tetap antarorganisasi, sehingga B2B. Penggunaan jaringan publik tidak mengubah pembeli bisnis menjadi konsumen pribadi."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 1; elaborasi kasus baru."},{"id":"practice-2-1","chapter":2,"topic":"Peran perantara","section":"s5","prompt":"Produsen menjual langsung melalui platform, melewati distributor lama. Platform kemudian mengurus pembayaran, reputasi dan pengiriman. Kesimpulan paling lengkap adalah…","reason":"Distributor tertentu dihapus, tetapi fungsi matching, trust dan distribusi tetap diperlukan serta dilaksanakan perantara baru. Satu rantai dapat memperlihatkan disintermediation dan reintermediation sekaligus pada peran berbeda.","options":["Distributor diganti; disintermediation tidak terjadi dalam rantai","Distributor tetap ada; platform hanya menjadi kanal komunikasinya","Distributor dilewati; fungsi perantara dibentuk ulang","Distributor dilewati; distribusi berubah menjadi fungsi pembeli"],"analysis":["Peniadaan distributor tetap dapat disebut disintermediation pada mata rantai tersebut meski muncul perantara baru.","Kasus menyatakan distributor lama dilewati dan platform melaksanakan fungsi transaksi.","Disintermediation terjadi pada distributor dan reintermediation pada layanan platform.","Pembeli tidak dinyatakan mengambil alih pembayaran, reputasi, dan pengiriman yang dikelola platform."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-2","chapter":2,"topic":"Struktur pasar","section":"s4","prompt":"Satu perusahaan membuka portal bagi 40 pemasok untuk mengajukan penawaran atas spesifikasi pembeliannya. Portal dimiliki dan diatur perusahaan tersebut. Klasifikasi terbaik adalah…","reason":"Pengendali merupakan satu organisasi pembeli dan calon penjualnya banyak. Itu private buy-side dalam taksonomi materi. Banyak pemasok tidak cukup untuk menyebut public many-to-many.","options":["Public marketplace dengan struktur many-to-many","Private marketplace dengan struktur buy-side","Public marketplace dengan struktur sell-side","Private marketplace dengan struktur sell-side"],"analysis":["Kasus hanya menyebut satu pembeli dan pengendali yang sama.","Satu pembeli mengatur pasar yang melibatkan banyak pemasok.","Tidak ada pemilik pihak ketiga atau satu penjual utama.","Sell-side berpusat pada satu penjual melayani banyak pembeli."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-3","chapter":2,"topic":"Dutch vs reverse auction","section":"s8","prompt":"Seorang penjual menawarkan satu mesin, memulai harga tinggi lalu menurunkannya sampai salah satu pembeli menerima. Pilihan mana paling tepat?","reason":"Arah harga menurun tidak menentukan reverse auction. Satu penjual menawarkan barang kepada banyak calon pembeli, dengan mekanisme Dutch auction. Reverse auction menempatkan banyak pemasok bersaing bagi satu pembeli.","options":["Double auction pada struktur banyak pihak","English auction dengan penawaran tertutup","Dutch auction pada struktur satu penjual","Reverse auction pada struktur satu pembeli"],"analysis":["Tidak ada banyak penawaran jual yang dicocokkan dengan penawaran beli.","English biasanya bid pembeli meningkat; mekanismenya berbeda dari kasus.","Harga turun sampai diterima, dengan satu penjual sebagai pusat.","Tidak ada satu pembeli yang mengundang persaingan banyak pemasok."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-4","chapter":2,"topic":"Storefront, mall, portal","section":"s6","prompt":"Situs X berisi direktori 200 toko dan mengirim pengunjung ke situs masing-masing untuk transaksi. Situs Y menjual katalog satu perusahaan. Pasangan paling tepat adalah…","reason":"X menggabungkan beberapa toko dengan pola referring mall. Y merupakan storefront satu penjual. Tidak adanya shared checkout tidak mencegah X diklasifikasikan mall dalam bentuk direktori.","options":["X storefront; Y corporate portal","X buy-side exchange; Y shared mall","X storefront; Y public exchange","X referring mall; Y storefront"],"analysis":["X bukan toko tunggal dan Y dinyatakan menjual produk.","Tidak ada organisasi pembeli pusat atau kumpulan toko di Y.","Kedua label mengabaikan struktur penjual yang disebutkan.","Jumlah toko dan lokasi penyelesaian transaksi membedakan keduanya."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-5","chapter":2,"topic":"Front end dan back end","section":"s3","prompt":"Pembeli melihat “pembayaran selesai” tetapi order tidak muncul di gudang. Log gateway menunjukkan pembayaran disetujui. Lokasi investigasi pertama yang paling relevan adalah…","reason":"Bukti menunjukkan antarmuka dan otorisasi merespons, tetapi handoff ke fulfillment gagal. Perlu memeriksa pencatatan status order dan integrasi gudang. Tidak cukup menilai tampilan berhasil sebagai bukti seluruh proses selesai.","options":["Reservasi kapasitas kurir dan pencetakan label","Indeks katalog dan validasi isi keranjang","Transisi status order dan integrasi fulfillment","Validasi kartu dan permintaan otorisasi ulang"],"analysis":["Ini tahap setelah gudang menerima order; kasus belum menunjukkan order mencapai tahap tersebut.","Pemilihan produk mendahului pembayaran; titik pertama yang terindikasi gagal adalah pemindahan order ke fulfillment.","Menelusuri sambungan setelah persetujuan pembayaran hingga order masuk antrean gudang.","Gateway sudah memberikan persetujuan; mengulang otorisasi belum menjelaskan hilangnya order dan berisiko duplikasi."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-6","chapter":2,"topic":"Crowdsourcing","section":"s11","prompt":"Kontes inovasi menerima 5.000 ide. Tim ingin memilih solusi teknis untuk batas biaya dan performa tertentu. Tahap berikut yang paling dapat dipertanggungjawabkan adalah…","reason":"Jumlah kontribusi menunjukkan partisipasi, belum membuktikan kelayakan. Solusi perlu dievaluasi dengan kriteria biaya/performa, dapat dimodifikasi, lalu diprioritaskan. Voting dapat menjadi input, bukan pengganti verifikasi teknis.","options":["Urutkan biaya usulan, lalu pilih estimasi terendah","Saring kelayakan, uji kriteria, lalu prioritaskan","Urutkan jumlah suara, lalu biayai prototipe teratas","Urutkan kebaruan, lalu pilih ide paling berbeda"],"analysis":["Estimasi biaya perlu diverifikasi dan dibandingkan dengan kebutuhan performa, bukan digunakan sendirian.","Menghubungkan seleksi dengan batas biaya dan performa yang telah ditetapkan.","Popularitas dapat menyaring perhatian tetapi tidak menggantikan kelayakan terhadap dua batas kasus.","Kebaruan penting untuk inovasi, tetapi ide baru bisa melanggar batas performa atau biaya."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-7","chapter":2,"topic":"AR vs visual search","section":"s10","prompt":"Aplikasi A mencari kursi serupa dari foto pengguna. Aplikasi B menampilkan model kursi digital di atas gambar ruang tamu secara langsung. Perbedaan yang paling tepat adalah…","reason":"A menggunakan gambar sebagai kueri pencarian. B menambahkan objek digital pada pandangan ruang nyata, sehingga AR. Kedua aplikasi dapat membantu keputusan, tetapi mekanisme representasinya berbeda.","options":["A virtual reality; B visual search","A social search; B crowdsourcing","A visual search; B augmented reality","A augmented reality; B virtual reality"],"analysis":["A tidak membuat lingkungan virtual; B menempatkan objek secara visual.","Kasus tidak menyebut relasi sosial atau kontribusi crowd.","Kueri visual berbeda dari overlay objek pada lingkungan nyata.","A tidak menambah objek ke lingkungan; B tidak menggantinya sepenuhnya."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-8","chapter":2,"topic":"Shopping cart","section":"s7","prompt":"Keranjang menahan pilihan pengguna selama sesi. Dalam pemetaan fungsi EC, penyimpanan pilihan ini merupakan bukti reservasi persediaan gudang.","reason":"Keranjang menyimpan item yang dipilih. Reservasi adalah komitmen stok oleh proses inventori; keduanya dapat dihubungkan, tetapi kasus hanya menyebut penyimpanan pilihan sehingga bukti reservasi belum ada.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Keranjang menyimpan item yang dipilih. Reservasi adalah komitmen stok oleh proses inventori; keduanya dapat dihubungkan, tetapi kasus hanya menyebut penyimpanan pilihan sehingga bukti reservasi belum ada.","Keranjang menyimpan item yang dipilih. Reservasi adalah komitmen stok oleh proses inventori; keduanya dapat dihubungkan, tetapi kasus hanya menyebut penyimpanan pilihan sehingga bukti reservasi belum ada."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-9","chapter":2,"topic":"Komunitas dan marketplace","section":"s9","prompt":"Komunitas profesional dengan keanggotaan terbatas dapat menggunakan wiki dan forum meskipun tidak memiliki mekanisme jual beli.","reason":"Komunitas dibedakan oleh kepentingan dan interaksi anggotanya. Marketplace berfungsi memfasilitasi pertukaran pasar. Tools kolaborasi tidak mewajibkan adanya transaksi komersial.","options":["Benar","Salah"],"analysis":["Komunitas dibedakan oleh kepentingan dan interaksi anggotanya. Marketplace berfungsi memfasilitasi pertukaran pasar. Tools kolaborasi tidak mewajibkan adanya transaksi komersial.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-2-10","chapter":2,"topic":"Metaverse dan interoperabilitas","section":"s10","prompt":"Mal virtual X mengekspor avatar dalam format yang dapat diimpor platform Y. Bukti itu menunjukkan interoperabilitas representasi avatar, tetapi belum membuktikan hak pakai barang virtual ikut berlaku di Y.","reason":"Portabilitas representasi dan pengakuan hak aset merupakan lapisan berbeda. Impor bentuk avatar menguji pertukaran data, sedangkan lisensi, identitas dan pengakuan transaksi membutuhkan aturan serta dukungan platform penerima.","options":["Benar","Salah"],"analysis":["Portabilitas representasi dan pengakuan hak aset merupakan lapisan berbeda. Impor bentuk avatar menguji pertukaran data, sedangkan lisensi, identitas dan pengakuan transaksi membutuhkan aturan serta dukungan platform penerima.","Menolak klaim ini tidak sesuai mekanisme kasus. Portabilitas representasi dan pengakuan hak aset merupakan lapisan berbeda. Impor bentuk avatar menguji pertukaran data, sedangkan lisensi, identitas dan pengakuan transaksi membutuhkan aturan serta dukungan platform penerima."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 2; elaborasi kasus baru."},{"id":"practice-3-1","chapter":3,"topic":"Omnichannel","section":"s3","prompt":"Retailer memiliki web dan toko, tetapi stok serta retur tidak terhubung. Pembeli online ditolak saat meminta retur di toko. Perbaikan yang paling langsung menuju omnichannel adalah…","reason":"Omnichannel menekankan kesinambungan pengalaman dan integrasi proses. Dua kanal yang berdiri sendiri baru menunjukkan multichannel. Menambah kanal lain tanpa menyatukan order, stok dan kebijakan hanya memperluas fragmentasi.","options":["Satukan identitas order, stok, dan prosedur retur","Satukan merek, promosi, dan kalender peluncuran","Satukan target omzet dan pelaporan kedua kanal","Satukan katalog, foto, dan deskripsi setiap produk"],"analysis":["Menghubungkan bukti transaksi dan pelaksanaan layanan lintas kanal.","Konsistensi komunikasi belum memungkinkan toko memproses retur order web.","Pelaporan bersama dapat mendukung koordinasi, tetapi transaksi dan kebijakan retur belum terintegrasi.","Konsistensi informasi produk tidak memberi kemampuan menerima atau membukukan retur lintas kanal."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-2","chapter":3,"topic":"Kesesuaian produk","section":"s1","prompt":"Dua produk memberi margin identik: e-book standar dan makanan segar dengan jendela kirim dua jam. Perbedaan desain operasi paling penting adalah…","reason":"Makanan segar membawa variasi kualitas, umur simpan dan kendala waktu fisik. Katalog sama baiknya tidak meniadakan kebutuhan kapasitas serta kondisi kirim. E-book memerlukan hak akses dan delivery digital, dengan kendala berbeda.","options":["Makanan memerlukan kendali lisensi dan hak unduh","Keduanya cukup memakai antrean fulfillment identik","Keduanya cukup memakai kapasitas server identik","Makanan memerlukan kendali kondisi dan slot kirim"],"analysis":["Kontrol ini lebih langsung terkait distribusi konten digital daripada kualitas makanan selama pengiriman.","Antrean generik mengabaikan kedaluwarsa, wilayah, dan kapasitas pengiriman makanan.","Kapasitas digital relevan untuk pemesanan, tetapi tidak menangani bottleneck pemenuhan fisik.","Umur simpan serta jendela dua jam menuntut kapasitas dan kondisi pengiriman fisik."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-3","chapter":3,"topic":"Integrasi e-tailing","section":"s2","prompt":"Katalog menunjukkan lima unit stok; tiga order hampir bersamaan diterima masing-masing dua unit. Pembayaran berhasil, tetapi gudang hanya memiliki lima. Kontrol yang paling langsung relevan adalah…","reason":"Masalahnya overselling karena total komitmen melebihi ketersediaan. Reservasi dan pemeriksaan konsisten pada proses order menangani sumber kegagalan. Menambah layanan purnajual membantu dampak, tetapi tidak mencegah kejadian.","options":["Pemeriksaan stok setiap awal sesi belanja pelanggan","Rekonsiliasi stok ketika picking gudang dimulai","Reservasi stok konsisten saat order dikonfirmasi","Sinkronisasi katalog setiap akhir batch pembayaran"],"analysis":["Pemeriksaan awal menjadi usang ketika pembeli lain membuat komitmen sebelum checkout.","Menemukan kekurangan sesudah janji dan pembayaran; berguna untuk audit tetapi terlambat mencegah overselling.","Komitmen order harus mengurangi ketersediaan secara konsisten meski permintaan hampir bersamaan.","Jeda batch masih memungkinkan beberapa order membaca stok yang sama sebelum pembaruan."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-4","chapter":3,"topic":"Channel conflict","section":"s11","prompt":"Produsen memberi diskon web besar, sementara dealer tetap membiayai demo dan layanan. Banyak pelanggan mencoba di dealer lalu membeli web. Pilihan paling menyasar akar konflik adalah…","reason":"Dealer menanggung aktivitas yang menciptakan nilai, tetapi transaksi berpindah sehingga kompensasinya hilang. Penyelarasan peran dan insentif menangani konflik ini. Menyamakan harga saja belum membagi biaya atau nilai pelayanan.","options":["Tambah target demo dan bonus berdasarkan kunjungan","Atur atribusi layanan dan pembagian imbalan kanal","Samakan harga katalog dan ukur omzet tiap kanal","Pisahkan segmen kanal berdasarkan usia pelanggan"],"analysis":["Menghargai aktivitas, tetapi tanpa hubungan kualitas atau konversi dapat mendorong demo yang tidak menghasilkan nilai.","Mengembalikan imbalan kepada kanal yang berkontribusi pada keputusan pembelian.","Harga seragam mengurangi satu pemicu, tetapi dealer masih dapat memberi demo tanpa memperoleh bagian transaksi.","Segmentasi usia tidak langsung mengatasi pelanggan yang memakai demo dealer lalu membeli di web."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-5","chapter":3,"topic":"Escrow dan trust","section":"s10","prompt":"Pembeli bersedia membayar jika kondisi barang cocok. Penjual enggan mengirim sebelum kepastian dana. Mekanisme yang paling langsung mengurangi risiko pertukaran berurutan adalah…","reason":"Escrow menahan dan melepaskan dana menurut syarat yang disepakati. Ini mengatasi siapa harus menyerahkan lebih dahulu. Rating membantu kepercayaan sebelum transaksi, tetapi tidak dengan sendirinya mengatur transfer dana saat sengketa.","options":["Escrow dengan bukti penerimaan dan aturan sengketa","Prapembayaran dengan verifikasi identitas penjual","Pascapembayaran dengan rating dan batas kredit","Transfer langsung dengan pelacakan pengiriman"],"analysis":["Dana ditahan pihak perantara dan dilepas berdasarkan syarat pertukaran yang disepakati.","Identitas mengurangi anonimitas, tetapi risiko penyerahan sebelum pemeriksaan tetap ditanggung pembeli.","Memindahkan risiko gagal bayar kepada penjual yang justru menolak mengirim tanpa kepastian dana.","Pelacakan menunjukkan pergerakan, bukan kesesuaian kondisi barang atau mekanisme penahanan dana."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-6","chapter":3,"topic":"Travel online","section":"s5","prompt":"Dua tiket memiliki harga awal sama. Tiket A tidak dapat diubah dan bagasi berbayar; tiket B lebih fleksibel dengan bagasi termasuk. Pembeli sering mengubah jadwal. Dasar perbandingan terbaik adalah…","reason":"Produk travel merupakan janji layanan dengan aturan. Harga awal sama tidak berarti nilai atau biaya total sama. Relevansi fleksibilitas harus dinilai terhadap pola perjalanan pengguna, bukan digeneralisasikan sebagai pilihan terbaik bagi semua.","options":["Harga awal dan biaya perubahan pada satu skenario","Rata-rata biaya penumpang pada seluruh rute","Banyaknya fleksibilitas tanpa menilai pemakaiannya","Biaya total dan ketentuan sesuai pola perjalanan"],"analysis":["Lebih baik daripada harga awal saja, tetapi mengabaikan bagasi dan kemungkinan perubahan yang berbeda.","Rata-rata umum dapat tidak mewakili frekuensi perubahan dan kebutuhan bagasi pengguna ini.","Fleksibilitas merupakan nilai bila sesuai kebutuhan; jumlah opsi saja bukan ukuran biaya total atau kecocokan.","Perubahan jadwal dan bagasi memengaruhi biaya serta manfaat yang relevan bagi pengguna kasus."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-7","chapter":3,"topic":"Online employment","section":"s6","prompt":"Portal kerja menerima tiga kali lebih banyak CV, tetapi proporsi yang lolos asesmen turun. Belum tersedia angka kelulusan absolut atau biaya penyaringan. Evaluasi mana paling tepat?","reason":"Proporsi dan jumlah absolut berbeda. Misalnya 100 CV × 30% menghasilkan 30 kandidat, sedangkan 300 × 20% menghasilkan 60 meski proporsinya turun. Bandingkan kandidat sesuai kriteria dan biaya per kandidat sebelum menyimpulkan kualitas atau efisiensi matching berubah.","options":["Simpulkan matching membaik dari total CV masuk","Bandingkan biaya iklan per CV sebelum dan sesudah","Uji jumlah kandidat layak dan biaya per kandidat","Simpulkan matching memburuk dari rasio kelulusan"],"analysis":["Input yang lebih besar belum membuktikan jumlah atau kualitas hasil dan efisiensi penyaringan.","Ini metrik akuisisi input; biaya per kandidat layak diperlukan untuk menilai hasil matching.","Pisahkan proporsi dari jumlah absolut, lalu ukur efisiensi menyaring kandidat yang benar-benar sesuai.","Rasio turun dapat bersamaan dengan jumlah kandidat layak naik; perlu denominator dan biaya."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-8","chapter":3,"topic":"Personalisasi dan customization","section":"s11","prompt":"Menampilkan produk berdasarkan riwayat pengguna dan membuat sepatu sesuai ukuran pesanan merupakan dua bentuk perubahan yang sama: keduanya hanya personalisasi informasi.","reason":"Rekomendasi mengubah informasi/pengalaman dan merupakan personalisasi. Pembuatan sepatu mengubah produk sehingga merupakan customization. Keduanya dapat digabung, tetapi objek yang diubah berbeda.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Rekomendasi mengubah informasi/pengalaman dan merupakan personalisasi. Pembuatan sepatu mengubah produk sehingga merupakan customization. Keduanya dapat digabung, tetapi objek yang diubah berbeda."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-9","chapter":3,"topic":"Online brokerage","section":"s7","prompt":"Aplikasi trading yang mengirim order secara elektronik masih dapat memerlukan broker serta bursa untuk memproses transaksi.","reason":"Antarmuka elektronik mendigitalkan akses, bukan otomatis menghilangkan seluruh lembaga perantara. Diagram materi menempatkan sistem broker dan koneksi ke bursa di belakang antarmuka pengguna.","options":["Benar","Salah"],"analysis":["Antarmuka elektronik mendigitalkan akses, bukan otomatis menghilangkan seluruh lembaga perantara. Diagram materi menempatkan sistem broker dan koneksi ke bursa di belakang antarmuka pengguna.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-3-10","chapter":3,"topic":"Flash sales dan kanal","section":"s3","prompt":"Retailer click-and-mortar menjual stok berlebih melalui flash sale daring. Dalam klasifikasi materi, flash sale menjelaskan mekanisme penawaran, sedangkan click-and-mortar menjelaskan struktur kanal.","reason":"Sumbu klasifikasi berbeda dapat berlaku bersama. Batas waktu penawaran menjelaskan flash sale; keberadaan kanal toko fisik dan online menjelaskan click-and-mortar. Perubahan mekanisme promosi tidak menghapus struktur kanal tersebut.","options":["Benar","Salah"],"analysis":["Sumbu klasifikasi berbeda dapat berlaku bersama. Batas waktu penawaran menjelaskan flash sale; keberadaan kanal toko fisik dan online menjelaskan click-and-mortar. Perubahan mekanisme promosi tidak menghapus struktur kanal tersebut.","Menolak klaim ini tidak sesuai mekanisme kasus. Sumbu klasifikasi berbeda dapat berlaku bersama. Batas waktu penawaran menjelaskan flash sale; keberadaan kanal toko fisik dan online menjelaskan click-and-mortar. Perubahan mekanisme promosi tidak menghapus struktur kanal tersebut."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 3; elaborasi kasus baru."},{"id":"practice-4-1","chapter":4,"topic":"Sumbu klasifikasi B2B","section":"s2","prompt":"Pabrik membeli pelumas untuk pemeliharaan mesin melalui kontrak tahunan dengan distributor khusus industri. Klasifikasi tujuan barang dan pola pembelian adalah…","reason":"Pelumas yang dipakai merawat mesin tidak masuk langsung ke produk akhir, sehingga termasuk MRO/indirect dalam konteks ini. Kontrak tahunan menunjukkan systematic sourcing. Sektor pemasok merupakan sumbu lain.","options":["Indirect/MRO; spot purchasing","Direct material; systematic sourcing","Indirect/MRO; systematic sourcing","Direct material; spot purchasing"],"analysis":["Tujuan barang benar, tetapi kontrak tahunan menunjukkan pola terencana.","Pola kontrak benar, tetapi tujuan penggunaan bukan bahan langsung.","Tujuan pemeliharaan dan hubungan kontraktual mendukung dua label ini.","Barang tidak menjadi komponen produk dan pembelian tidak insidental."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-2","chapter":4,"topic":"E-tendering vs reverse auction","section":"s7","prompt":"Universitas mengundang proposal implementasi sistem dengan pendekatan teknis berbeda. Evaluasi mencakup integrasi, layanan dan biaya. Menjadikan harga terendah satu-satunya dasar pemenang terutama bermasalah karena…","reason":"Reverse auction paling jelas ketika penawaran dapat dibandingkan terhadap spesifikasi yang setara. Dalam kasus solusi heterogen, harga tidak mewakili seluruh nilai atau risiko. Tender elektronik dapat memakai evaluasi multikriteria tanpa lelang berulang.","options":["Biaya pembelian belum dikonversi menjadi komisi","Solusi belum setara pada dimensi yang dinilai","Jumlah pemasok belum sama dengan jumlah pembeli","Tender elektronik belum mempunyai harga pembuka"],"analysis":["Komisi merupakan model imbalan perantara, bukan prasyarat membandingkan proposal pengadaan.","Harga tidak merangkum perbedaan integrasi, layanan, serta risiko implementasi.","Reverse auction tidak mensyaratkan jumlah kedua sisi sama; satu pembeli dan banyak pemasok justru lazim.","Evaluasi proposal multikriteria tidak memerlukan mekanisme harga pembuka lelang."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-3","chapter":4,"topic":"Total cost of ownership","section":"s6","prompt":"Vendor A menawarkan Rp90 juta dengan operasi tahunan Rp25 juta. Vendor B menawarkan Rp110 juta dengan operasi Rp15 juta. Untuk tiga tahun tanpa diskonto/nilai sisa, pilihan berbasis total biaya adalah…","reason":"Hitung komponen pada horizon yang sama. A = 90 + 3×25 = 165 juta; B = 110 + 3×15 = 155 juta. Harga awal yang lebih murah tidak menjamin total biaya lebih rendah.","options":["B lebih rendah Rp10 juta selama tiga tahun","A lebih rendah Rp20 juta selama tiga tahun","A lebih rendah Rp10 juta selama tiga tahun","B lebih rendah Rp30 juta selama tiga tahun"],"analysis":["Selisih biaya awal tertutup oleh penghematan operasi tiga tahun.","Ini selisih harga awal yang mengabaikan biaya operasi.","A justru memiliki total biaya Rp10 juta lebih tinggi.","Ini penghematan operasi sebelum mengurangi tambahan harga awal B."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-4","chapter":4,"topic":"Desktop vs maverick purchasing","section":"s8","prompt":"Pegawai memesan alat tulis dari katalog kontrak memakai batas anggaran otomatis. Pegawai lain membeli item sama dari situs luar tanpa persetujuan. Pasangan paling tepat adalah…","reason":"Desktop purchasing dapat mendesentralisasikan order sambil mempertahankan kontrol kontrak. Maverick purchasing melewati ketentuan pengadaan. Kedua aktivitas dilakukan individu, tetapi tingkat kepatuhannya berbeda.","options":["Reverse auction; forward auction","Desktop purchasing; maverick purchasing","Maverick purchasing; desktop purchasing","Strategic sourcing; group purchasing"],"analysis":["Tidak ada kompetisi bid pada kedua pembelian tersebut.","Yang pertama terkendali katalog/anggaran; yang kedua melewati prosedur.","Membalik arti kontrol proses yang dijelaskan dalam kasus.","Kasus membahas pelaksanaan order, bukan pemilihan strategi atau agregasi."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-5","chapter":4,"topic":"Vertical vs horizontal exchange","section":"s9","prompt":"Platform mempertemukan perusahaan dari banyak industri untuk membeli perlengkapan kantor. Karakter pasar utamanya adalah…","reason":"Horizontal menjangkau kebutuhan lintas industri, sering untuk input umum seperti MRO. Vertical melayani rantai atau kebutuhan industri tertentu. Jenis barang dan cakupan industri perlu dibedakan dari kepemilikan platform.","options":["Private sell-side karena barangnya terstandar","Buy-side tunggal karena kebutuhan pembeli serupa","Horizontal exchange untuk kebutuhan lintas industri","Vertical exchange karena pembelinya perusahaan"],"analysis":["Standarisasi barang tidak menentukan kepemilikan satu penjual.","Kesamaan kebutuhan tidak berarti hanya ada satu pembeli.","Perlengkapan umum digunakan oleh pembeli dari berbagai sektor.","Status pembeli bisnis tidak menjadikan pasar khusus satu industri."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-6","chapter":4,"topic":"Buying center","section":"s1","prompt":"Dalam pengadaan laptop, laboratorium menyusun spesifikasi, unit pengadaan menegosiasi kontrak, dan pimpinan menyetujui pilihan. Pasangan peran lab dan unit pengadaan adalah…","reason":"Peran buying center ditentukan aktivitas. Lab memengaruhi kriteria teknis; unit pengadaan menangani sourcing/negosiasi. Otoritas keputusan akhir pada pimpinan berbeda dari dua peran tersebut.","options":["Decider dan gatekeeper","Gatekeeper dan user","Buyer dan decider","Influencer dan buyer"],"analysis":["Kasus menempatkan keputusan final pada pimpinan dan tidak menyebut pengendalian akses.","Kedua kegiatan yang disebut bukan pembatasan informasi atau penggunaan akhir.","Menyusun spesifikasi bukan otomatis membeli; negosiasi bukan persetujuan final.","Spesifikasi memengaruhi pilihan; negosiasi/pengadaan merupakan fungsi buyer."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-7","chapter":4,"topic":"Collaborative commerce","section":"s11","prompt":"Pemasok dan produsen berbagi forecast serta menyelaraskan rencana produksi sebelum ada order pembelian. Nilai utama aktivitas tersebut adalah…","reason":"Kolaborasi mengoordinasikan keputusan lintas perusahaan, bukan hanya mengeksekusi transaksi. Berbagi rencana dapat memperbaiki keselarasan pasokan-permintaan. Belum adanya PO tidak membuat kegiatan tersebut berada di luar c-commerce.","options":["Menyelaraskan rencana permintaan dan pasokan","Mengotomasi pencocokan invoice dengan penerimaan","Mengonsolidasikan pembelian untuk diskon volume","Membandingkan bid untuk menentukan harga kontrak"],"analysis":["Kolaborasi praorder menyambungkan forecast dan kapasitas, bukan hanya memproses transaksi yang sudah terjadi.","Pencocokan invoice terjadi setelah order dan penerimaan; tahap yang dibahas adalah perencanaan.","Agregasi order kelompok berbeda dari berbagi forecast dan menyelaraskan rencana dua mitra.","Penemuan harga melalui penawaran bukan kegiatan dominan dalam kasus perencanaan bersama."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-8","chapter":4,"topic":"EDI dan B2B","section":"s1","prompt":"Perusahaan dapat menjalankan B2B tanpa EDI, dan penggunaan EDI menunjukkan mekanisme pertukaran dokumen, bukan dengan sendirinya model pendapatan.","reason":"B2B mengklasifikasikan hubungan organisasi. EDI merupakan salah satu cara dokumen terstruktur dipertukarkan. Model pendapatan tetap perlu dijelaskan terpisah dari sarana komunikasi.","options":["Benar","Salah"],"analysis":["B2B mengklasifikasikan hubungan organisasi. EDI merupakan salah satu cara dokumen terstruktur dipertukarkan. Model pendapatan tetap perlu dijelaskan terpisah dari sarana komunikasi.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-9","chapter":4,"topic":"Group purchasing","section":"s8","prompt":"Dua kelompok memesan total unit yang sama dengan kepastian pembayaran dan biaya distribusi setara. Dalam diskon yang semata-mata berbasis volume, kelompok beranggota lebih banyak memperoleh dasar tawar lebih kuat.","reason":"Unit yang dikomitmenkan sama dan faktor lain dibuat setara. Jumlah anggota tidak menambah volume, sehingga aturan diskon volume tidak memberi keunggulan tambahan. Jika risiko, biaya atau relasi berubah, kasusnya berbeda.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Unit yang dikomitmenkan sama dan faktor lain dibuat setara. Jumlah anggota tidak menambah volume, sehingga aturan diskon volume tidak memberi keunggulan tambahan. Jika risiko, biaya atau relasi berubah, kasusnya berbeda.","Unit yang dikomitmenkan sama dan faktor lain dibuat setara. Jumlah anggota tidak menambah volume, sehingga aturan diskon volume tidak memberi keunggulan tambahan. Jika risiko, biaya atau relasi berubah, kasusnya berbeda."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-4-10","chapter":4,"topic":"Supply chain dan sistem","section":"s10","prompt":"CRM berfokus pada hubungan pelanggan dan SRM pada pemasok; keduanya dapat berkontribusi pada koordinasi rantai pasok meskipun objek hubungannya berbeda.","reason":"Hubungan pelanggan menyediakan sinyal kebutuhan, sementara pemasok menyediakan kemampuan pasokan. Integrasi informasi membantu koordinasi tanpa menjadikan CRM dan SRM sinonim.","options":["Benar","Salah"],"analysis":["Hubungan pelanggan menyediakan sinyal kebutuhan, sementara pemasok menyediakan kemampuan pasokan. Integrasi informasi membantu koordinasi tanpa menjadikan CRM dan SRM sinonim.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 4; elaborasi kasus baru."},{"id":"practice-5-1","chapter":5,"topic":"Kategori e-government","section":"s3","prompt":"Dinas A dan dinas B bertukar data untuk mempercepat verifikasi bantuan. Portal yang sama juga menyediakan penggajian pegawai. Dua fungsi tersebut paling tepat dipetakan sebagai…","reason":"Klasifikasi ditentukan relasi pada fungsi tertentu. Pertukaran antardinas merupakan G2G; layanan langsung kepada pegawai merupakan G2E dan dapat meningkatkan IEE. Satu portal tidak wajib memiliki satu kategori tunggal.","options":["G2C; G2B dengan manfaat IEE","G2E; G2G dengan manfaat G2C","G2B; G2C dengan manfaat G2E","G2G; G2E dengan manfaat IEE"],"analysis":["Data verifikasi ditukar antardinas, bukan langsung dengan warga/bisnis.","Pertukaran antarinstansi bukan layanan pegawai; penggajian bukan antarinstansi.","Tidak ada bisnis pada fungsi pertama atau warga umum pada fungsi kedua.","Membedakan relasi antarlembaga dan pemerintah-pegawai."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-2","chapter":5,"topic":"E-voting","section":"s3","prompt":"Sistem e-voting menghitung suara cepat dan melakukan autentikasi pemilih. Namun tidak tersedia bukti untuk memeriksa ulang hasil penghitungan. Penilaian yang paling tepat adalah…","reason":"Autentikasi dan kecepatan tidak menjamin integritas hasil dapat diverifikasi. Materi menekankan keamanan serta audit. Ketiadaan audit trail yang memadai menyisakan pertanyaan tentang pemeriksaan hasil, bukan membuktikan hasil pasti salah.","options":["Autentikasi harus diulang pada tahap rekapitulasi","Kapasitas hitung harus disetarakan antarperangkat","Ketersediaan server harus menjadi prioritas tunggal","Kemampuan audit hasil belum memadai"],"analysis":["Mengulang pemeriksaan identitas tidak menghasilkan bukti bahwa suara dihitung dengan benar.","Kesetaraan performa tidak menyelesaikan ketiadaan bukti audit; kecepatan pun sudah dinyatakan baik.","Availability penting, tetapi bukti kasus secara spesifik menunjukkan masalah verifikasi hasil.","Tanpa bukti pemeriksaan ulang, autentikasi dan kecepatan tidak membuktikan hasil dapat diaudit."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-3","chapter":5,"topic":"LMS vs KM","section":"s4","prompt":"Universitas ingin mengelola jadwal, penugasan, nilai dan akses modul. Perusahaan mitranya ingin menyimpan solusi teknisi, menemukan pakar dan memakai ulang praktik kerja. Pasangan sistem dominan adalah…","reason":"LMS mengelola proses pembelajaran, sedangkan KM mengelola pengetahuan organisasi. Kedua sistem dapat berbagi konten, tetapi fungsi dominan kasus berbeda. E-learning juga dapat memperbaiki operasi secara tidak langsung.","options":["LMS untuk universitas; ELS saja untuk perusahaan","Repositori untuk universitas; direktori pakar untuk perusahaan","LMS untuk universitas; KM untuk perusahaan","KM untuk universitas; LMS untuk perusahaan"],"analysis":["ELS membantu menemukan pakar, tetapi belum mencakup penyimpanan, validasi, dan reuse seluruh pengetahuan.","Masing-masing hanya komponen; belum mencakup administrasi nilai maupun seluruh siklus pengetahuan.","Administrasi pembelajaran berbeda dari pengelolaan solusi serta keahlian untuk pemakaian organisasi.","Membalik fungsi dominan: jadwal/nilai memerlukan LMS, sedangkan reuse praktik kerja menekankan KM."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-4","chapter":5,"topic":"Knowledge refinement","section":"s5","prompt":"Tim mengambil solusi forum, menguji pada tiga konfigurasi, lalu menambahkan kondisi kapan solusi gagal. Tahap KM yang paling dominan adalah…","reason":"Aktivitas utama adalah memvalidasi serta memberi konteks agar pengetahuan dapat diterapkan dengan tepat. Sumbernya forum tidak menentukan tahap. Ini refinement, meskipun dapat didahului capture dan diikuti dissemination.","options":["Store: mengarsipkan dokumen ke repositori","Disseminate: menyalurkan hasil ke pengguna","Refine: memvalidasi dan memberi konteks","Capture: mencatat pengalaman yang tersedia"],"analysis":["Tidak menjelaskan pengujian dan penambahan syarat penerapan.","Belum ada tindakan distribusi sebagai fokus utama kasus.","Pengujian serta batas penerapan merupakan inti refinement.","Pengambilan awal ada, tetapi kasus menekankan validasi berikutnya."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-5","chapter":5,"topic":"Expert location system","section":"s5","prompt":"Pertanyaan tidak memiliki jawaban cocok dalam repositori. Sistem menemukan teknisi yang relevan dan meminta solusi. Agar pembelajaran organisasi berlanjut, langkah setelah solusi tersedia sebaiknya…","reason":"ELS tidak hanya menghubungkan orang. Solusi perlu ditinjau, disampaikan dan ditambahkan ke repositori agar kasus serupa tidak selalu mengulang pencarian pakar. Validasi menjaga kualitas pengetahuan yang dibagikan.","options":["Tinjau solusi, kirim, dan perbarui repositori","Kirim solusi, tutup tiket, dan perbarui profil pakar","Arsipkan jawaban mentah, lalu tutup akses kasus","Tambahkan kata kunci, lalu arahkan semua kasus ke pakar"],"analysis":["Menutup kasus sekaligus mengubah jawaban pakar menjadi pengetahuan yang dapat dipakai ulang.","Profil membantu pencarian berikutnya, tetapi isi solusi tidak tersedia untuk reuse bila tidak ditangkap.","Penyimpanan tanpa peninjauan dan akses yang sesuai belum membentuk pengetahuan yang dapat digunakan.","Memperbaiki routing, tetapi mempertahankan ketergantungan pada pakar untuk masalah berulang."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-6","chapter":5,"topic":"E-health sebagai sistem","section":"s6","prompt":"Rumah sakit menghubungkan hasil laboratorium dengan rekam pasien dan memberi dokter akses sesuai peran. Tim ingin menguji apakah integrasi memperbaiki koordinasi pelayanan, bukan hanya menambah data. Pasangan manfaat dan indikator mana paling langsung?","reason":"Integrasi membuat hasil pemeriksaan tersedia dalam konteks pasien. Salah satu konsekuensi yang dapat diuji adalah berkurangnya pemeriksaan berulang akibat informasi sebelumnya tidak ditemukan. Tetap periksa alasan klinis, komposisi pasien, dan baseline; tidak semua pemeriksaan ulang merupakan duplikasi yang sia-sia.","options":["Kapasitas pelayanan; evaluasi jumlah akun dokter","Ketepatan klinis; evaluasi jumlah hasil yang diunggah","Efisiensi administrasi; evaluasi kecepatan unduh saja","Kontinuitas informasi; evaluasi duplikasi pemeriksaan"],"analysis":["Akun merupakan kesiapan akses, bukan kapasitas layanan atau bukti informasi dipakai dalam keputusan.","Volume unggahan tidak mengukur ketepatan diagnosis; perlu indikator klinis yang sesuai.","Kecepatan akses dapat membantu, tetapi belum menguji koordinasi pelayanan yang menjadi tujuan integrasi.","Rekam yang terhubung membantu dokter melihat hasil sebelumnya; penurunan tes duplikat menguji penggunaan informasi itu."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-7","chapter":5,"topic":"C2C dan platform","section":"s7","prompt":"Dua individu bertransaksi barang bekas lewat platform yang menyediakan escrow dan mengenakan biaya layanan. Relasi barang dan layanan platform paling tepat dibedakan sebagai…","reason":"Barang tetap dipertukarkan antarindividu, sehingga C2C. Platform menyediakan layanan bisnis yang dapat dibedakan dari relasi barang. Klasifikasi tidak berubah hanya karena pembayaran melalui perantara.","options":["C2C pada barang; intrabusiness pada layanan platform","B2B2C pada barang; B2B pada layanan platform","C2C pada barang; layanan bisnis oleh platform","B2C pada barang; C2C pada layanan platform"],"analysis":["Layanan platform melibatkan pihak luar, bukan proses yang hanya berlangsung di dalam satu organisasi.","Tidak dinyatakan ada dua bisnis dalam rantai penjual barang; penjualnya individu.","Individu bertukar barang, sementara platform menjalankan kegiatan bisnis layanan perantara.","Membalik unit analisis: platform bukan pemilik barang pada fakta kasus."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-8","chapter":5,"topic":"M-government","section":"s3","prompt":"Peringatan bencana dari pemerintah ke ponsel warga dapat sekaligus diklasifikasikan G2C dan m-government.","reason":"G2C menyebut relasi pelakunya, sedangkan m-government menyebut penggunaan kanal/platform mobile. Dua dimensi tersebut dapat berlaku sekaligus pada satu layanan.","options":["Benar","Salah"],"analysis":["G2C menyebut relasi pelakunya, sedangkan m-government menyebut penggunaan kanal/platform mobile. Dua dimensi tersebut dapat berlaku sekaligus pada satu layanan.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-9","chapter":5,"topic":"E-learning dan hasil","section":"s4","prompt":"Dashboard LMS mencatat nilai asesmen praktik dan penyelesaian video secara terpisah. Untuk tujuan mengukur kompetensi melakukan prosedur, completion video merupakan pengganti yang setara dengan asesmen praktik.","reason":"Completion membuktikan aktivitas penyelesaian konten, sedangkan asesmen praktik menguji penerapan prosedur. Kedua metrik dapat saling melengkapi, tetapi kesetaraan validitasnya tidak mengikuti dari keduanya berada di LMS.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Completion membuktikan aktivitas penyelesaian konten, sedangkan asesmen praktik menguji penerapan prosedur. Kedua metrik dapat saling melengkapi, tetapi kesetaraan validitasnya tidak mengikuti dari keduanya berada di LMS.","Completion membuktikan aktivitas penyelesaian konten, sedangkan asesmen praktik menguji penerapan prosedur. Kedua metrik dapat saling melengkapi, tetapi kesetaraan validitasnya tidak mengikuti dari keduanya berada di LMS."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-5-10","chapter":5,"topic":"E-books dan perangkat","section":"s4","prompt":"Dua perangkat membuka berkas e-book yang sama. Keberhasilan membuka teks memberikan dasar yang cukup untuk menyatakan dukungan video dan interaktivitas keduanya setara.","reason":"Kompatibilitas teks berbeda dari kemampuan merender multimedia, menjalankan interaksi, atau terhubung untuk pembaruan. Kesetaraan harus diuji untuk fitur yang diklaim, bukan disimpulkan dari satu kemampuan dasar.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Kompatibilitas teks berbeda dari kemampuan merender multimedia, menjalankan interaksi, atau terhubung untuk pembaruan. Kesetaraan harus diuji untuk fitur yang diklaim, bukan disimpulkan dari satu kemampuan dasar.","Kompatibilitas teks berbeda dari kemampuan merender multimedia, menjalankan interaksi, atau terhubung untuk pembaruan. Kesetaraan harus diuji untuk fitur yang diklaim, bukan disimpulkan dari satu kemampuan dasar."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 5; elaborasi kasus baru."},{"id":"practice-6-1","chapter":6,"topic":"Atribut mobile","section":"s2","prompt":"Dua orang di lokasi dan waktu yang sama membuka aplikasi. Urutan penawaran berbeda karena riwayat minat masing-masing. Atribut yang paling langsung ditunjukkan adalah…","reason":"Lokasi dan waktu sengaja dibuat sama agar pembeda yang diuji adalah penyesuaian individu. Ini personalization. Ubiquity, convenience dan interactivity bisa hadir, tetapi tidak menjelaskan variasi urutan berdasarkan minat.","options":["Personalization berdasarkan profil pengguna","Localization berdasarkan koordinat pengguna","Ubiquity berdasarkan akses lintas tempat","Interactivity berdasarkan komunikasi dua arah"],"analysis":["Perbedaan isi ditentukan preferensi masing-masing individu.","Koordinat sama sehingga tidak menjelaskan perbedaan yang dinyatakan.","Kasus tidak membandingkan kemampuan akses di lokasi berbeda.","Tidak ada percakapan atau pertukaran respons yang diuji."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-2","chapter":6,"topic":"Fondasi dan kemampuan tambahan","section":"s3","prompt":"Toko mobile berjalan dengan katalog, order, pembayaran dan jaringan nirkabel. Tim ingin menambahkan rekomendasi berbasis AI. Kesimpulan yang tepat adalah…","reason":"EC mobile sudah terjadi tanpa rekomendasi AI. Sistem cerdas dapat menambah relevansi, tetapi bukan syarat definisional agar transaksi mobile berlangsung. Prasyarat layanan dasar harus dipisahkan dari peningkatan kemampuan.","options":["AI diperlukan untuk setiap keputusan pembayaran","AI memperkaya layanan yang telah berfungsi","AI menjadi prasyarat bila katalog bersifat dinamis","AI menjadi prasyarat bila pembeli memakai ponsel"],"analysis":["Otorisasi dapat mengikuti aturan serta prosedur tanpa model AI; fraud scoring cerdas merupakan kemungkinan tambahan.","AI merupakan kemampuan tambahan; transaksi mobile sudah dapat berjalan melalui fondasi yang disebutkan.","Katalog dinamis dapat diperbarui dengan aturan dan database tanpa inferensi model AI.","Perangkat mobile dan kanal transaksi tidak menyaratkan rekomendasi atau kecerdasan buatan."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-3","chapter":6,"topic":"Mapping, navigation, tracking","section":"s5","prompt":"Aplikasi menampilkan titik-titik toko, memberi instruksi belok menuju toko terpilih, lalu memperbarui posisi kurir. Tiga fungsi dominannya berturut-turut adalah…","reason":"Representasi tempat, panduan perjalanan, dan pemantauan pergerakan adalah fungsi yang berbeda. Ketiganya dapat memakai peta yang sama. Penentuan kategori harus mengikuti aktivitas, bukan tampilan peta semata.","options":["Tracking; mapping; navigation","Mapping; tracking; navigation","Mapping; navigation; tracking","Navigation; tracking; mapping"],"analysis":["Posisi toko statis bukan pelacakan; kurir bergerak bukan instruksi belok.","Dua fungsi terakhir dibalik: petunjuk arah berbeda dari pemantauan.","Titik lokasi, panduan rute, dan pemantauan posisi sesuai urutan kasus.","Titik toko tidak memandu perjalanan; urutan dua fungsi lain juga tertukar."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-4","chapter":6,"topic":"Alur LBS","section":"s4","prompt":"Koordinat pengguna akurat, tetapi aplikasi merekomendasikan toko yang sudah tutup karena data jam operasional lama. Komponen yang paling langsung perlu diperbaiki adalah…","reason":"Akurasi posisi bukan satu-satunya syarat relevansi layanan lokasi. Kasus menunjukkan data bisnis yang dipakai untuk menafsirkan koordinat sudah basi. Sensor baru tidak memperbarui informasi jam operasional.","options":["Kalibrasi sensor dan interval pembacaan lokasi","Penambahan radius dan jumlah hasil pencarian","Penghitungan rute dan estimasi waktu perjalanan","Pemeliharaan data tempat dan aturan rekomendasi"],"analysis":["Memperbaiki posisi tidak memperbarui informasi jam buka toko.","Memperbanyak kandidat tidak memisahkan toko buka dan tutup bila datanya tetap usang.","Rute membantu perjalanan setelah pemilihan, tetapi jam operasional salah tetap menyebabkan saran tidak sesuai.","Jam operasional merupakan atribut tempat yang usang; koordinat telah dinyatakan akurat."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-5","chapter":6,"topic":"Context-aware computing","section":"s5","prompt":"Aplikasi menunda notifikasi promosi saat pengguna berada dalam sesi kuliah yang tercantum di kalender. GPS tidak digunakan. Penilaian yang tepat adalah…","reason":"Konteks dapat berupa waktu dan aktivitas. Lokasi merupakan satu jenis konteks, bukan prasyarat seluruh context-aware computing. Fungsi ini memakai informasi situasi untuk menyesuaikan perilaku layanan.","options":["Context-aware berbasis waktu dan aktivitas","LBS berbasis koordinat dari jadwal kalender","Mapping berbasis kategori mata kuliah","Tracking berbasis perpindahan antarjaringan"],"analysis":["Penyesuaian menggunakan situasi pengguna yang relevan.","Kalender tidak dengan sendirinya menyediakan koordinat lokasi.","Tidak ada representasi geografis dalam kegiatan yang dijelaskan.","Kasus tidak memantau gerakan atau perpindahan jaringan."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-6","chapter":6,"topic":"Bandwidth dan respons","section":"s7","prompt":"Kapasitas koneksi digandakan, tetapi respons checkout tetap lambat. Pengukuran menunjukkan server membutuhkan empat detik memproses setiap order. Langkah paling relevan adalah…","reason":"Kapasitas transfer bukan satu-satunya komponen waktu respons. Bukti kasus menunjuk pemrosesan server sebagai hambatan. Bandwidth tambahan dapat berguna untuk transfer, tetapi tidak otomatis mengurangi waktu komputasi backend.","options":["Perpendek interval polling status pembayaran","Perbaiki pemrosesan order di sisi backend","Perbesar kapasitas transfer pada sisi pengguna","Kurangi ukuran gambar pada katalog perangkat"],"analysis":["Mempercepat pemeriksaan status dapat menambah beban tanpa mempercepat pemrosesan order.","Pengukuran menempatkan empat detik pada proses server; intervensi pertama harus menyasar bottleneck tersebut.","Dapat membantu transfer, tetapi kapasitas telah digandakan tanpa perubahan dan dominasi waktu berada di server.","Mengurangi unduhan katalog tidak langsung memperpendek komputasi order yang telah diukur."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-7","chapter":6,"topic":"IoT dan nilai proses","section":"s6","prompt":"Sensor gudang mengirim suhu setiap menit, tetapi tidak ada alarm atau tindakan ketika batas terlewati. Tambahan yang paling langsung mengubah data menjadi nilai operasi adalah…","reason":"Penginderaan dan transmisi belum menyelesaikan masalah bisnis. Aturan, notifikasi yang tepat, pemilik tindakan dan pencatatan respons membentuk loop keputusan. Lebih banyak data tidak membantu jika tidak digunakan.","options":["Aturan ambang, eskalasi, dan prosedur respons","Pengukuran lebih rapat dan arsip lebih panjang","Kalibrasi sensor dan validasi format pesan","Replikasi penyimpanan dan kompresi telemetri"],"analysis":["Menghubungkan deteksi dengan tanggung jawab serta tindakan saat kondisi keluar dari rentang.","Menambah data tetapi tidak menentukan siapa bertindak saat suhu melewati batas.","Menjaga mutu input penting; kasus secara spesifik kekurangan respons terhadap data yang diterima.","Meningkatkan ketahanan serta efisiensi data, belum menghubungkan kejadian dengan aksi operasi."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-8","chapter":6,"topic":"Kompleksitas fitur","section":"s7","prompt":"Menambahkan fitur mobile dapat meningkatkan cakupan tugas sekaligus meningkatkan beban belajar; kedua dampak itu tidak saling meniadakan.","reason":"Manfaat fungsional dan kompleksitas adalah dimensi berbeda. Desain perlu mempertimbangkan kebutuhan pengguna, konteks dan prioritas tugas. Lebih banyak fitur tidak otomatis lebih baik atau lebih buruk.","options":["Benar","Salah"],"analysis":["Manfaat fungsional dan kompleksitas adalah dimensi berbeda. Desain perlu mempertimbangkan kebutuhan pengguna, konteks dan prioritas tugas. Lebih banyak fitur tidak otomatis lebih baik atau lebih buruk.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-9","chapter":6,"topic":"IoT dan M2M","section":"s6","prompt":"Sensor dan aktuator bertukar pesan pada jaringan lokal tertutup. Aktivitas ini dapat diklasifikasikan M2M tanpa bukti bahwa layanan IoT untuk pengguna akhir telah tersedia.","reason":"M2M berfokus pada komunikasi antarmesin. IoT dalam alur layanan yang dibahas menambahkan pengelolaan, pengolahan data dan aplikasi; bukti pertukaran pesan saja tidak menetapkan kelengkapan seluruh lapisan itu.","options":["Benar","Salah"],"analysis":["M2M berfokus pada komunikasi antarmesin. IoT dalam alur layanan yang dibahas menambahkan pengelolaan, pengolahan data dan aplikasi; bukti pertukaran pesan saja tidak menetapkan kelengkapan seluruh lapisan itu.","Menolak klaim ini tidak sesuai mekanisme kasus. M2M berfokus pada komunikasi antarmesin. IoT dalam alur layanan yang dibahas menambahkan pengelolaan, pengolahan data dan aplikasi; bukti pertukaran pesan saja tidak menetapkan kelengkapan seluruh lapisan itu."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-6-10","chapter":6,"topic":"Manfaat potensial","section":"s2","prompt":"Fitur informasi real-time dapat membantu keputusan belanja, tetapi tanpa data akurat fitur itu belum menjamin kepuasan konsumen meningkat.","reason":"Ketepatan waktu berbeda dari ketepatan isi. Informasi cepat yang salah justru dapat menghasilkan keputusan buruk. Karena itu manfaat harus dievaluasi bersama kualitas data dan hasil yang relevan bagi pengguna.","options":["Benar","Salah"],"analysis":["Ketepatan waktu berbeda dari ketepatan isi. Informasi cepat yang salah justru dapat menghasilkan keputusan buruk. Karena itu manfaat harus dievaluasi bersama kualitas data dan hasil yang relevan bagi pengguna.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 6; elaborasi kasus baru."},{"id":"practice-7-1","chapter":7,"topic":"Group buying","section":"s3","prompt":"Kelompok A memiliki 80 anggota dengan total komitmen 80 unit. Kelompok B memiliki 8 anggota dengan total komitmen 400 unit. Pemasok memberi diskon menurut volume pasti, dengan biaya distribusi sama. Dasar tawar yang lebih kuat adalah…","reason":"Kasus menetapkan volume pasti sebagai dasar diskon dan menyamakan biaya distribusi. Kelompok B menggabungkan permintaan lebih besar walau anggotanya lebih sedikit. Jangan mengganti jumlah unit dengan jumlah akun.","options":["Kelompok A karena permintaan lebih tersebar","Kelompok B karena komitmen unit lebih besar","Kelompok A karena jumlah anggota lebih banyak","Keduanya sama karena memakai group buying"],"analysis":["Sebaran tidak dinyatakan sebagai kriteria diskon dan biaya disamakan.","Sesuai variabel yang dipakai pemasok pada kondisi kasus.","Jumlah anggota tidak sama dengan volume pembelian.","Nama mekanisme tidak membuat skala permintaan identik."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-2","chapter":7,"topic":"Taxonomy vs folksonomy","section":"s5","prompt":"Pegawai memberi tag bebas pada dokumen, lalu pengelola memetakan sinonim ke kategori resmi. Interpretasi paling tepat adalah…","reason":"Kontribusi tag berasal dari pengguna, sedangkan pemetaan resmi merupakan kurasi terstruktur. Enterprise 2.0 tidak menuntut penghapusan seluruh kontrol. Kedua pola dapat dipadukan untuk partisipasi dan kemudahan penemuan.","options":["Folksonomy murni tanpa pengelolaan kategori","Personalisasi menggantikan klasifikasi dokumen","Folksonomy dikombinasikan dengan taxonomy","Taxonomy murni tanpa kontribusi pengguna"],"analysis":["Mengabaikan pemetaan resmi yang dilakukan pengelola.","Tidak ada penyesuaian isi per individu sebagai fokus kasus.","Tag emergen dan kategori terkelola hadir bersama.","Mengabaikan tag bebas yang dibuat pegawai."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-3","chapter":7,"topic":"Data management vs analytics","section":"s4","prompt":"Tim A menghapus ulasan duplikat dan memperbaiki format tanggal. Tim B menguji hubungan sentimen dengan retur. Tim C menampilkan hasil mingguan. Urutan fungsi dominan adalah…","reason":"Pembersihan memperbaiki kualitas data; pengujian hubungan menafsirkan data; penyajian hasil merupakan reporting. Fungsi dapat terintegrasi dalam sistem yang sama tanpa menjadikan istilahnya sinonim.","options":["Analytics; reporting; data management","Reporting; data management; analytics","Personalization; analytics; crowdsourcing","Data management; analytics; reporting"],"analysis":["Pembersihan bukan pengujian pola; grafik bukan pengelolaan format.","Menukar tujuan utama ketiga aktivitas yang dijelaskan.","Tidak ada penyesuaian pengguna atau pengumpulan tugas crowd.","Membedakan kualitas data, interpretasi, dan penyajian hasil."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-4","chapter":7,"topic":"Kualitas UGC","section":"s4","prompt":"Produk P memiliki rating 4,9 dari 8 ulasan; Q memiliki 4,7 dari 2.000 ulasan. Distribusi pengguna dan verifikasi pembelian belum diketahui. Kesimpulan paling hati-hati adalah…","reason":"Rata-rata dan ukuran sampel belum menjelaskan bias, keterwakilan, verifikasi serta kecocokan kebutuhan. Data lebih banyak dapat meningkatkan stabilitas tertentu, tetapi tidak otomatis menghapus bias. Tidak sah memastikan produk terbaik hanya dari dua angka ini.","options":["Gabungkan keduanya memakai rata-rata tanpa bobot","Perlu konteks ulasan sebelum memastikan pilihan","Utamakan P dengan mengabaikan jumlah pengulas","Utamakan Q dengan mengabaikan komposisi pengulas"],"analysis":["Menggabungkan dua produk menjadi satu angka menghilangkan perbedaan objek keputusan dan jumlah pengulas.","Rata-rata dan ukuran sampel harus dilihat bersama distribusi, bias seleksi, kecocokan pengguna dan verifikasi.","Rata-rata tinggi pada sampel kecil belum cukup memberi kepastian kualitas.","Sampel besar memperkuat estimasi pada populasinya, tetapi bias dan ketidakcocokan pengguna tetap mungkin."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-5","chapter":7,"topic":"Hambatan adopsi","section":"s7","prompt":"Pegawai antusias memakai jejaring internal dan integrasi teknis sudah berhasil. Direksi menunda perluasan karena manfaat finansial belum dapat dibuktikan dibanding biaya. Hambatan dominan adalah…","reason":"Kasus menyingkirkan resistensi pengguna dan kegagalan integrasi. Masalahnya justifikasi nilai investasi. Pilot dengan baseline, biaya dan ukuran hasil relevan lebih tepat daripada sekadar pelatihan ulang antarmuka.","options":["Keterbatasan jaringan pada perangkat kerja","Justifikasi imbal balik investasi","Resistensi pegawai terhadap perubahan","Integrasi sistem lama dengan sistem baru"],"analysis":["Tidak ada bukti kendala jaringan yang menunda keputusan.","Direksi mempertanyakan manfaat relatif terhadap biaya.","Kasus menyatakan pegawai antusias, sehingga bukan bukti utama.","Integrasi sudah dinyatakan berhasil."],"answer":1,"type":"mc","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-6","chapter":7,"topic":"ROI dan manfaat","section":"s7","prompt":"Biaya pilot jejaring pengetahuan Rp120 juta. Estimasi penghematan tervalidasi Rp150 juta pada periode yang sama. ROI sederhana dan batas interpretasinya adalah…","reason":"ROI = (150−120)/120 = 25%. Validasi manfaat dan kesamaan periode membuat perhitungan bermakna dalam asumsi kasus. Hasil itu belum otomatis berlaku bagi skala lebih besar dengan struktur biaya berbeda.","options":["20%; dapat mengabaikan baseline manfaat","30%; cukup berdasarkan banyaknya posting","25%; perlu uji ulang ketika skala berubah","125%; berlaku tetap pada semua skala"],"analysis":["20% memakai manfaat sebagai denominator dan mengabaikan dasar pembanding.","30 adalah selisih juta, bukan persentase; posting bukan manfaat finansial.","Perhitungan benar dan tidak menggeneralisasikan di luar asumsi.","125% adalah manfaat/biaya, bukan pengembalian bersih; klaim tetap juga berlebihan."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-7","chapter":7,"topic":"Social shopping aids","section":"s2","prompt":"Pembeli menyimpan tautan produk, membagikannya ke teman, lalu menerima saran. Fungsi yang paling langsung menggambarkan tindakan menyimpan dan berbagi tautan adalah…","reason":"Social bookmarking menyusun serta membagikan rujukan. Referral program memerlukan mekanisme rujukan/insentif tertentu, sedangkan sponsored review menyangkut hubungan pembuat konten dan sponsor. Tidak semua berbagi tautan otomatis afiliasi.","options":["Collaborative filtering","Social comparison shopping","Social bookmarking","Social recommendation engine"],"analysis":["Memerlukan inferensi preferensi dari pola antarpengguna atau item; saran langsung teman belum membuktikan algoritme itu.","Membandingkan penawaran dapat menjadi penggunaan lanjut, tetapi menyimpan dan berbagi tautan adalah fungsi yang ditanyakan.","Objek yang disimpan dan dibagikan adalah tautan; komentar teman dapat melengkapinya.","Mesin rekomendasi menyeleksi atau mengurutkan berdasarkan model/sinyal; kasus menekankan penyimpanan tautan pengguna."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-8","chapter":7,"topic":"KM dan komunitas","section":"s6","prompt":"Forum yang menguji solusi, mengoreksi kesalahan, dan memberi batas penggunaan dapat melakukan knowledge refinement meskipun sumber ide awalnya juga forum.","reason":"Tahap KM mengikuti kegiatan. Menguji dan memberi konteks merupakan refinement, sedangkan melahirkan ide adalah creation. Platform yang sama dapat mendukung banyak tahap siklus.","options":["Benar","Salah"],"analysis":["Tahap KM mengikuti kegiatan. Menguji dan memberi konteks merupakan refinement, sedangkan melahirkan ide adalah creation. Platform yang sama dapat mendukung banyak tahap siklus.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-9","chapter":7,"topic":"Social commerce dan multimedia","section":"s2","prompt":"Video ditampilkan sama kepada semua pengunjung. Pengayaan ini meningkatkan richness informasi, sedangkan personalization baru terbukti jika pengalaman disesuaikan dengan karakteristik pengguna.","reason":"Richness menjelaskan kedalaman atau kekayaan informasi. Personalisasi memerlukan penyesuaian bagi pengguna; format video sendiri bukan bukti penyesuaian. Video yang sama dapat kaya informasi tanpa personalisasi.","options":["Benar","Salah"],"analysis":["Richness menjelaskan kedalaman atau kekayaan informasi. Personalisasi memerlukan penyesuaian bagi pengguna; format video sendiri bukan bukti penyesuaian. Video yang sama dapat kaya informasi tanpa personalisasi.","Menolak klaim ini tidak sesuai mekanisme kasus. Richness menjelaskan kedalaman atau kekayaan informasi. Personalisasi memerlukan penyesuaian bagi pengguna; format video sendiri bukan bukti penyesuaian. Video yang sama dapat kaya informasi tanpa personalisasi."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-7-10","chapter":7,"topic":"Indikator aktivitas","section":"s7","prompt":"Jumlah posting yang naik dapat menjadi indikator partisipasi, tetapi belum cukup untuk menyimpulkan jejaring perusahaan meningkatkan laba.","reason":"Posting mengukur aktivitas. Hubungan ke laba memerlukan jalur manfaat, biaya dan bukti hasil. Penilaian dapat memakai metrik antara, tetapi tidak boleh langsung menyamakan aktivitas dengan keuntungan.","options":["Benar","Salah"],"analysis":["Posting mengukur aktivitas. Hubungan ke laba memerlukan jalur manfaat, biaya dan bukti hasil. Penilaian dapat memakai metrik antara, tetapi tidak boleh langsung menyamakan aktivitas dengan keuntungan.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 7; elaborasi kasus baru."},{"id":"practice-8-1","chapter":8,"topic":"Authentication vs authorization","section":"s4","prompt":"Pegawai berhasil login menggunakan MFA, tetapi masih dapat mengubah rekening pemasok di luar kewenangannya. Kontrol yang paling langsung kurang adalah…","reason":"MFA meningkatkan bukti identitas, bukan pembatasan tindakan setelah login. Kasus menunjukkan kegagalan otorisasi. Sistem perlu menentukan hak perubahan data sensitif sesuai peran dan proses persetujuan.","options":["Confidentiality atas rekaman rekening pemasok","Availability atas layanan pemeliharaan pemasok","Authorization atas perubahan rekening pemasok","Authentication ulang saat sesi pegawai dimulai"],"analysis":["Kerahasiaan melindungi pembacaan, sedangkan kasus menyoroti perubahan di luar kewenangan.","Ketersediaan memastikan akses layanan, bukan bahwa tindakan diizinkan bagi pelaku tertentu.","Identitas telah diverifikasi; masalahnya hak pengguna menjalankan tindakan tertentu.","Verifikasi ulang identitas tidak membatasi kewenangan jika aturan akses masih mengizinkan perubahan."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-2","chapter":8,"topic":"Payment lifecycle","section":"s5","prompt":"Issuer menyetujui transaksi kartu. Merchant belum melakukan capture dan dana belum diterima. Pernyataan yang paling tepat adalah…","reason":"Authorization merupakan keputusan persetujuan, bukan settlement. Capture dan proses clearing/settlement berikutnya masih diperlukan sesuai mekanisme jaringan. Tampilan disetujui tidak membuktikan penerimaan dana merchant.","options":["Settlement selesai; otorisasi menunggu capture","Capture selesai; clearing berarti verifikasi login","Semua tahap selesai; dana hanya belum terlihat","Otorisasi selesai; settlement belum terbukti"],"analysis":["Membalik dependensi dan menganggap dana sudah selesai.","Kasus menyatakan capture belum dilakukan; clearing bukan login.","Tidak ada bukti seluruh tahap sudah terjadi.","Membedakan keputusan issuer dari penyelesaian dana."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-3","chapter":8,"topic":"CTR dan CPM","section":"s3","prompt":"Kampanye menghabiskan Rp900.000 untuk 150.000 tayangan dan 3.000 klik. Pasangan CTR dan CPM yang benar adalah…","reason":"CTR = 3.000/150.000 = 2%. CPM = 900.000/150.000×1.000 = Rp6.000. CTR menggunakan klik sebagai numerator; CPM mengukur biaya per seribu tayangan.","options":["2% dan Rp6.000","2% dan Rp300","5% dan Rp6.000","50% dan Rp300"],"analysis":["Kedua denominator mengikuti definisi yang tepat.","Rp300 adalah biaya per klik, bukan biaya per seribu tayangan.","CPM benar, tetapi perhitungan CTR tidak sesuai 3.000/150.000.","Menggunakan rasio yang keliru dan menukar CPM dengan CPC."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-4","chapter":8,"topic":"Threat vs vulnerability","section":"s4","prompt":"Prosedur pemberian akses tidak pernah ditinjau, sehingga akun mantan pegawai masih aktif. Penyerang kemudian memakainya untuk mengambil data. Pasangan kondisi dan kejadian adalah…","reason":"Akun yang masih dapat digunakan serta prosedur usang merupakan kelemahan. Pengambilan data oleh penyerang merupakan tindakan/insiden yang memanfaatkannya. Klasifikasi ini membantu memilih kontrol yang sesuai akar masalah.","options":["Threat; vulnerability yang belum tereksploitasi","Control; risiko yang belum menjadi kejadian","Incident; ancaman yang masih bersifat potensial","Vulnerability; tindakan ancaman yang terealisasi"],"analysis":["Membalik kondisi dan aksi; kelemahan sudah dipakai mengambil data.","Prosedur tidak efektif bukan bukti kontrol bekerja, dan pengambilan data sudah menjadi kejadian.","Akun usang adalah kondisi kelemahan; aksi penyerang tidak lagi sekadar potensi.","Akun aktif yang seharusnya dicabut adalah kelemahan; penyalahgunaannya merupakan aksi serangan."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-5","chapter":8,"topic":"Balanced scorecard","section":"s8","prompt":"Tujuan perusahaan adalah mempercepat order-to-delivery. KPI “median waktu picking gudang” paling langsung berada pada perspektif…","reason":"Picking adalah bagian proses operasi internal. Dampaknya dapat menjalar ke kepuasan dan keuangan, tetapi objek ukuran tetap proses. Perspektif dibedakan dari dampak akhirnya agar scorecard tidak mencampur semua metrik.","options":["Pelanggan dan pasar","Pembelajaran dan pertumbuhan","Proses bisnis internal","Keuangan perusahaan"],"analysis":["Tidak secara langsung mengukur persepsi atau perilaku pelanggan.","Tidak mengukur kemampuan/kompetensi yang mendukung proses.","Ukuran langsung mengamati kecepatan kegiatan operasional.","Tidak mengukur pendapatan, margin atau pengembalian."],"answer":2,"type":"mc","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-6","chapter":8,"topic":"Magic Quadrant","section":"s8","prompt":"Dalam evaluasi suatu pasar, vendor dinilai memiliki visi arah pasar kuat tetapi kemampuan eksekusi relatif tertinggal. Kategori yang dituju adalah…","reason":"Sumbu visi dan eksekusi perlu dibaca terpisah. Visionaries kuat pada visi relatif terhadap eksekusi. Kategori tidak otomatis menentukan vendor terbaik bagi semua kebutuhan; evaluasi tetap kontekstual.","options":["Challengers","Leaders","Niche Players","Visionaries"],"analysis":["Kategori ini relatif kuat pada eksekusi, bukan pasangan dalam kasus.","Memerlukan kekuatan pada kedua dimensi yang dinilai.","Bukan label spesifik bagi kombinasi visi kuat-eksekusi tertinggal.","Cocok dengan visi kuat dan eksekusi yang belum setara."],"answer":3,"type":"mc","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-7","chapter":8,"topic":"Markup vs margin","section":"s6","prompt":"Biaya produk Rp80.000. Perusahaan menetapkan markup 25% dari biaya. Harga jual dan margin terhadap harga jual adalah…","reason":"Markup biaya = 25%×80.000 = 20.000, sehingga harga 100.000. Margin = 20.000/100.000 = 20%. Denominator berbeda menjelaskan mengapa markup dan margin tidak sama.","options":["Rp100.000 dan 20%","Rp100.000 dan 25%","Rp106.667 dan 25%","Rp95.000 dan 15%"],"analysis":["Menambahkan markup biaya lalu membagi laba kotor dengan harga jual.","Harga benar, tetapi margin memakai denominator biaya secara keliru.","Ini mendekati harga untuk target margin 25%, bukan markup biaya 25%.","Tidak mengikuti markup 25% dari biaya Rp80.000."],"answer":0,"type":"mc","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-8","chapter":8,"topic":"First-mover advantage","section":"s6","prompt":"Pelopor pasar dapat memperoleh pengenalan merek lebih awal sekaligus menanggung biaya eksperimen dan edukasi pasar yang tinggi.","reason":"Keuntungan waktu masuk tidak menghilangkan biaya menjadi pelopor. Keunggulan dan beban dapat muncul bersamaan; pengikut bahkan bisa belajar dari eksperimen awal.","options":["Benar","Salah"],"analysis":["Keuntungan waktu masuk tidak menghilangkan biaya menjadi pelopor. Keunggulan dan beban dapat muncul bersamaan; pengikut bahkan bisa belajar dari eksperimen awal.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-9","chapter":8,"topic":"Digital currency","section":"s5","prompt":"Pembayaran sepatu lewat dompet digital mendigitalkan instrumen pembayaran. Dalam model tiga dimensi materi, fakta itu menjadikan pengiriman fisik sepatu bagian dari pure EC.","reason":"Digitasi satu dimensi tidak mendigitalkan dimensi lain. Pengiriman sepatu tetap fisik sehingga transaksi campuran/partial EC; sifat instrumen pembayaran tidak mengubah objek atau metode fulfillment.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Digitasi satu dimensi tidak mendigitalkan dimensi lain. Pengiriman sepatu tetap fisik sehingga transaksi campuran/partial EC; sifat instrumen pembayaran tidak mengubah objek atau metode fulfillment.","Digitasi satu dimensi tidak mendigitalkan dimensi lain. Pengiriman sepatu tetap fisik sehingga transaksi campuran/partial EC; sifat instrumen pembayaran tidak mengubah objek atau metode fulfillment."],"answer":1,"type":"tf","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"practice-8-10","chapter":8,"topic":"Assessment dan improvement","section":"s7","prompt":"Dalam siklus strategi, assessment membandingkan hasil dengan sasaran, sedangkan improvement memilih serta menjalankan tindak lanjut atas temuan.","reason":"Evaluasi mengidentifikasi kesenjangan; perbaikan menindaklanjutinya. Keduanya memberi umpan balik untuk putaran strategi berikut, dan tidak harus menunggu semua aktivitas organisasi berhenti.","options":["Benar","Salah"],"analysis":["Evaluasi mengidentifikasi kesenjangan; perbaikan menindaklanjutinya. Keduanya memberi umpan balik untuk putaran strategi berikut, dan tidak harus menunggu semua aktivitas organisasi berhenti.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"practice","source":"Materi modul 8; elaborasi kasus baru."},{"id":"exam-5-1","chapter":5,"topic":"G2G dan tujuan kinerja","section":"s3","prompt":"Saat banjir, tiga instansi sudah memiliki aplikasi masing-masing. Masalah utama adalah verifikasi lintas instansi memakan enam jam karena data korban dicatat ulang. Pilih pasangan intervensi dan indikator yang paling langsung menguji perbaikan G2G.","reason":"Masalahnya koordinasi data antarlembaga, bukan semata akses warga. Intervensi yang menyambungkan verifikasi dan ukuran waktu antarlembaga menguji mekanisme G2G. Indikator dari domain lain dapat berguna tetapi tidak langsung menjawab hambatan ini.","options":["Pertukaran data antarlembaga; waktu verifikasi bersama","Portal pengaduan warga; waktu mengisi formulir pribadi","Aplikasi payroll pegawai; waktu menghitung tunjangan","Katalog pengadaan darurat; waktu menerima penawaran","Dashboard investasi TI; rasio pemakaian anggaran"],"analysis":["Intervensi dan metrik tepat pada hubungan yang menjadi hambatan.","Mengukur G2C, sementara data sudah tersendat antarinstansi.","Mengukur layanan pegawai dan efisiensi HR, bukan verifikasi bantuan.","Mendukung pengadaan G2B/B2G, bukan pertukaran catatan korban.","Mendukung tata kelola internal, tetapi tidak mengukur hambatan yang ditetapkan."],"answer":0,"type":"mc","pool":"exam","source":"Pola Q1-04; S5 15–19; B5 3, 5–6."},{"id":"exam-5-2","chapter":5,"topic":"Cakupan e-government","section":"s3","prompt":"Pemerintah membuka forum bagi warga untuk mengusulkan dan menilai solusi banjir. Instansi meninjau usulan lalu menjelaskan tindak lanjutnya. Selain portal informasi dan tender yang terpisah, bagaimana fungsi forum ini paling tepat diklasifikasikan?","reason":"E-government dalam definisi luas meliputi layanan, transaksi, operasi dan partisipasi. Forum solusi publik dapat termasuk government 2.0. Soal lama yang mengecualikan pemecahan masalah bersama tidak dapat diperlakukan sebagai larangan konseptual universal.","options":["Forum menjadi G2G karena solusi diputuskan instansi","Forum menjadi IEE karena ide diproses secara internal","Forum menjadi G2E karena peserta membantu pekerjaan","Forum menjadi G2B karena hasilnya bernilai ekonomis","Forum menjadi partisipasi publik dalam government 2.0"],"analysis":["Siapa memutuskan tidak mengubah interaksi pemerintah–warga menjadi relasi antarpemerintah.","Pemrosesan internal dapat mendukungnya, tetapi aktivitas utama yang dihadapi warga adalah partisipasi.","Memberi kontribusi tidak menjadikan warga pegawai pemerintah.","Nilai ekonomis tidak membuktikan peserta bertindak sebagai bisnis.","Pemerintah memakai interaksi warga untuk fungsi publik; sesuai perluasan partisipatif e-government."],"answer":4,"type":"mc","pool":"exam","source":"Pola Q1-08 diperjelas; B5 2–7 tentang e-government dan Government 2.0."},{"id":"exam-5-3","chapter":5,"topic":"G2E dan IEE","section":"s3","prompt":"Aplikasi X memungkinkan pegawai melihat slip gaji. Aplikasi Y mengotomasi rekonsiliasi pengadaan tanpa interaksi pegawai sebagai penerima layanan. Manakah pembacaan batas G2E–IEE yang paling tepat?","reason":"G2E menekankan hubungan pemerintah dengan pegawai sebagai penerima layanan. IEE menekankan hasil efisiensi/efektivitas proses internal. X dapat memberi keduanya; Y dapat menjadi IEE tanpa harus berupa layanan G2E.","options":["X hanya IEE; Y terutama layanan G2E","X dan Y G2G karena keduanya internal","X dan Y G2C karena pegawai juga warga","X adalah G2E; IEE terbatas pada pengadaan","X adalah G2E dan dapat IEE; Y terutama IEE"],"analysis":["Slip gaji melayani pegawai, sedangkan Y tidak dinyatakan demikian.","Internal tidak otomatis relasi antarlembaga pemerintahan.","Gunakan peran pada transaksi, bukan semua identitas yang dimiliki orang.","IEE lebih luas dan juga dapat mencakup payroll serta proses lainnya.","Mengakui tumpang tindih kategori tanpa menyamakan seluruh cakupannya."],"answer":4,"type":"mc","pool":"exam","source":"Pola Q1-16; S5 17; B5 6."},{"id":"exam-5-4","chapter":5,"topic":"Keamanan dan audit e-voting","section":"s3","prompt":"Panitia memiliki anggaran untuk memperbaiki mesin voting. Kebutuhan yang ditetapkan adalah identitas pemilih sah, suara tidak berubah, dan hasil dapat diverifikasi ulang. Proposal mana yang paling lengkap mencakup kebutuhan tersebut?","reason":"Tiga kebutuhan berbeda harus dilayani bersama: keabsahan pemilih, integritas suara, dan kemampuan memeriksa hasil. Satu fitur tidak dapat diasumsikan menggantikan semuanya. Kunci lama yang meremehkan security tidak dipakai sebagai dasar.","options":["Registrasi pemilih, kerahasiaan suara, kapasitas hitung","Bukti audit, replikasi server, enkripsi penyimpanan","Autentikasi pemilih, integritas rekaman, bukti audit","Autentikasi pemilih, enkripsi kanal, server cadangan","Kontrol akses admin, integritas rekaman, rekap cepat"],"analysis":["Registrasi belum memastikan pemilih yang mengakses sah; kerahasiaan/kapasitas tidak menggantikan audit integritas.","Audit ada, tetapi replikasi dan enkripsi tidak dengan sendirinya mengautentikasi pemilih atau memastikan suara tidak diubah.","Mencakup tiga kebutuhan berbeda yang eksplisit dalam kasus.","Mendukung identitas, kanal, dan availability; belum menyediakan bukti pemeriksaan hasil.","Integritas sebagian tercakup; keabsahan pemilih dan audit tidak dipenuhi oleh kontrol admin serta kecepatan."],"answer":2,"type":"mc","pool":"exam","source":"Pola Q1-17 dikoreksi; S5 11–12; B5 4–5."},{"id":"exam-5-5","chapter":5,"topic":"Klasifikasi peran G2C","section":"s3","prompt":"Orang yang sama melakukan lima aktivitas digital berikut. Aktivitas mana paling langsung merupakan G2C ketika diklasifikasikan berdasarkan perannya pada transaksi?","reason":"Satu orang dapat bertindak sebagai warga, pegawai pemerintah atau wakil bisnis. Pembayaran pajak pribadi melalui portal pemerintah menempatkannya sebagai warga. Kategori tidak ditentukan identitas orang secara permanen.","options":["Memeriksa tunjangan sebagai pegawai suatu dinas","Menyinkronkan data antardinas sebagai operator","Membeli buku bekas dari akun mahasiswa lain","Mengajukan dokumen kependudukan untuk dirinya","Mengirim tender atas nama perusahaan tempatnya bekerja"],"analysis":["Ia menerima layanan dalam peran pegawai, yaitu G2E.","Aktivitas menghubungkan unit pemerintah, sehingga G2G.","Hubungan transaksi terjadi antarindividu, bukan dengan pemerintah.","Pemerintah melayani individu dalam perannya sebagai warga.","Ia mewakili bisnis dalam relasi B2G/G2B."],"answer":3,"type":"mc","pool":"exam","source":"Pola Q1-20; S5 7–8; B5 4."},{"id":"exam-5-6","chapter":5,"topic":"Ruang lingkup e-health","section":"s6","prompt":"Sistem hasil laboratorium dan penjadwalan konsultasi elektronik dikelompokkan sebagai e-health. Pengelompokan ini tetap sesuai definisi meskipun pembayaran konsultasi dilakukan di loket.","reason":"E-health mencakup informasi, koordinasi dan pelayanan kesehatan melalui sistem elektronik. Kanal pembayaran adalah dimensi lain; tidak adanya pembayaran online tidak menghapus fungsi informasi atau penjadwalan dalam cakupan e-health.","options":["Benar","Salah"],"analysis":["E-health mencakup informasi, koordinasi dan pelayanan kesehatan melalui sistem elektronik. Kanal pembayaran adalah dimensi lain; tidak adanya pembayaran online tidak menghapus fungsi informasi atau penjadwalan dalam cakupan e-health.","Menolak klaim ini tidak sesuai mekanisme kasus. E-health mencakup informasi, koordinasi dan pelayanan kesehatan melalui sistem elektronik. Kanal pembayaran adalah dimensi lain; tidak adanya pembayaran online tidak menghapus fungsi informasi atau penjadwalan dalam cakupan e-health."],"answer":0,"type":"tf","pool":"exam","source":"Pola Q1-06; S5 36–37; B5 20–21."},{"id":"exam-5-7","chapter":5,"topic":"E-learning dan KM","section":"s4","prompt":"Pelatihan elektronik dapat memperbaiki operasi perusahaan melalui peningkatan kompetensi, tetapi fakta itu belum membuat e-learning dan KM menjadi istilah yang sama.","reason":"Sasaran langsung e-learning adalah pembelajaran individu, sementara KM mengelola pengetahuan untuk penggunaan organisasi. Pengaruh belajar pada operasi masuk akal; kesamaan dampak tidak menghapus perbedaan mekanisme.","options":["Benar","Salah"],"analysis":["Sasaran langsung e-learning adalah pembelajaran individu, sementara KM mengelola pengetahuan untuk penggunaan organisasi. Pengaruh belajar pada operasi masuk akal; kesamaan dampak tidak menghapus perbedaan mekanisme.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Pola Q1-09 diperjelas; S5 33; B5 15."},{"id":"exam-5-8","chapter":5,"topic":"Kemampuan LMS","section":"s4","prompt":"Sistem yang mengotomasi pendaftaran, jadwal, akses konten dan pencatatan nilai menjalankan fungsi LMS walaupun kontennya dibuat oleh pengajar di luar sistem.","reason":"LMS mengelola program pembelajaran dan tidak mensyaratkan semua materi harus dibuat di dalamnya. Asal konten berbeda dari kemampuan administrasi dan penyampaiannya.","options":["Benar","Salah"],"analysis":["LMS mengelola program pembelajaran dan tidak mensyaratkan semua materi harus dibuat di dalamnya. Asal konten berbeda dari kemampuan administrasi dan penyampaiannya.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Pola Q1-11; S5 32; B5 13."},{"id":"exam-5-9","chapter":5,"topic":"Pendorong e-learning","section":"s4","prompt":"Perusahaan lintas zona waktu memilih webinar wajib pada satu jam yang sama. Pilihan kanal online itu telah menyelesaikan hambatan keserempakan waktu yang menjadi alasan awal adopsi.","reason":"Webinar sinkron mengurangi kebutuhan berada di tempat yang sama, tetapi tetap mengharuskan waktu yang sama. Hambatan zona waktu memerlukan desain asinkron, alternatif sesi, atau mekanisme lain; digitalisasi kanal saja belum menyelesaikannya.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Webinar sinkron mengurangi kebutuhan berada di tempat yang sama, tetapi tetap mengharuskan waktu yang sama. Hambatan zona waktu memerlukan desain asinkron, alternatif sesi, atau mekanisme lain; digitalisasi kanal saja belum menyelesaikannya.","Webinar sinkron mengurangi kebutuhan berada di tempat yang sama, tetapi tetap mengharuskan waktu yang sama. Hambatan zona waktu memerlukan desain asinkron, alternatif sesi, atau mekanisme lain; digitalisasi kanal saja belum menyelesaikannya."],"answer":1,"type":"tf","pool":"exam","source":"Pola Q1-19; S5 22–27; B5 8–10."},{"id":"exam-5-10","chapter":5,"topic":"Tahap KM berdasarkan aktivitas","section":"s5","prompt":"Komunitas hanya mengusulkan ide baru tanpa memvalidasi, memberi konteks, atau memperbaikinya. Tahap yang paling langsung terbukti adalah knowledge refinement.","reason":"Bukti yang diberikan menunjukkan creation. Refinement memerlukan pengolahan seperti pengujian, koreksi atau konteks agar dapat diterapkan. Komunitas dapat melakukan refinement, tetapi aktivitas itu belum terjadi dalam kasus ini.","options":["Benar","Salah"],"analysis":["Pernyataan melampaui bukti atau menyamakan konsep berbeda. Periksa bagian klaim yang dikoreksi dalam penjelasan.","Bukti yang diberikan menunjukkan creation. Refinement memerlukan pengolahan seperti pengujian, koreksi atau konteks agar dapat diterapkan. Komunitas dapat melakukan refinement, tetapi aktivitas itu belum terjadi dalam kasus ini."],"answer":1,"type":"tf","pool":"exam","source":"Pola Q1-27 diperjelas; S5 34–35; B5 15–17."},{"id":"exam-6-1","chapter":6,"topic":"Personalisasi vs lokasi","section":"s2","prompt":"Aplikasi menunjukkan promo makan siang berbeda kepada pengguna dengan preferensi diet berbeda, meskipun keduanya berada di gedung dan jam yang sama. Tim ingin menjelaskan penyebab perbedaan konten, bukan fitur aplikasi secara umum. Atribut mana paling relevan?","reason":"Kasus menahan lokasi serta waktu tetap dan memvariasikan preferensi individu. Faktor pembeda yang disebut adalah personalisasi. Menyebut atribut lain yang juga mungkin dimiliki aplikasi tidak menjelaskan variasi ini.","options":["Ubiquity","Localization","Interactivity","Convenience","Personalization"],"analysis":["Menjelaskan jangkauan akses, bukan perbedaan isi antarindividu.","Lokasi sama sehingga bukan variabel pembeda kasus.","Kasus tidak menyoroti komunikasi timbal balik.","Kemudahan tidak secara spesifik menjelaskan penggunaan preferensi diet.","Konten disesuaikan dengan kebutuhan masing-masing pengguna."],"answer":4,"type":"mc","pool":"exam","source":"Pola Q1-01; materi penghubung mobile."},{"id":"exam-6-2","chapter":6,"topic":"Fondasi teknis m-commerce","section":"s3","prompt":"Arsitek mengaudit layanan mobile yang dapat menerima order tanpa rekomendasi otomatis. Komponen mana merupakan kemampuan tambahan, sehingga ketiadaannya tidak dengan sendirinya menggugurkan klasifikasi m-commerce?","reason":"Klasifikasi mobile ditentukan aktivitas EC melalui perangkat/kanal bergerak. Rekomendasi cerdas dapat menambah kemampuan tetapi bukan syarat definisional. Komponen akses, komunikasi dan transaksi mendukung fungsi dasar pada arsitektur yang dijelaskan.","options":["Perangkat bergerak sebagai sarana akses pengguna","Mesin rekomendasi berbasis model cerdas","Antarmuka untuk memasukkan pesanan pengguna","Konektivitas antara klien dan layanan transaksi","Layanan yang memproses status order pembeli"],"analysis":["Perangkat/akses bergerak menjadi dasar konteks mobile yang ditetapkan.","Order dapat berlangsung tanpa fitur rekomendasi tersebut.","Layanan memerlukan cara pengguna menyampaikan pilihan/order.","Arsitektur jaringan pada kasus membutuhkan pertukaran permintaan.","Pemrosesan order merupakan fungsi pokok layanan yang diaudit."],"answer":1,"type":"mc","pool":"exam","source":"Pola Q1-02; taksonomi prasyarat vs kemampuan tambahan."},{"id":"exam-6-3","chapter":6,"topic":"Komponen LBS","section":"s4","prompt":"Aplikasi parkir sudah mengetahui koordinat pengguna, tetapi belum dapat menentukan area parkir mana yang berdekatan dan sesuai jam operasional. Fungsi apa yang paling langsung melengkapi alur lokasi tersebut?","reason":"Koordinat perlu dipadankan dengan data geografis dan atribut layanan. GIS/database tempat mendukung pencarian kedekatan serta kondisi buka. Menambah presisi posisi saja tidak menghasilkan informasi lokasi parkir yang belum dimodelkan.","options":["Penghitungan rute dan estimasi waktu tempuh","Pelacakan posisi dan penyimpanan riwayat perjalanan","Rendering peta dan penyederhanaan simbol lokasi","Pengolahan spasial dan data atribut tempat","Triangulasi sinyal dan kalibrasi sensor posisi"],"analysis":["Memerlukan tujuan yang sesuai; rute sendiri belum menyaring parkir berdasarkan lokasi dan jam buka.","Mengikuti pergerakan pengguna, bukan melengkapi data area parkir serta status operasinya.","Menyajikan informasi visual, tetapi tampilan tidak menggantikan query spasial serta atribut tempat.","Menggabungkan kedekatan koordinat dengan jam operasional untuk menentukan kandidat yang sesuai.","Berfungsi memperoleh posisi; posisi sudah tersedia dan belum menyediakan atribut area parkir."],"answer":3,"type":"mc","pool":"exam","source":"Pola Q1-07; materi penghubung LBS."},{"id":"exam-6-4","chapter":6,"topic":"Manfaat mobile dan evaluasi","section":"s7","prompt":"Pilot aplikasi belanja memberi stok real-time. Waktu mencari barang turun, tetapi data stok sering keliru dan pembatalan naik. Klaim hasil mana yang paling kuat didukung bukti?","reason":"Bukti menunjukkan perbaikan pada waktu pencarian dan penurunan kualitas pemenuhan. Tidak cukup menyimpulkan kepuasan/keuntungan meningkat. Manfaat satu tahap dapat dibarengi kerugian tahap lain dalam proses end-to-end.","options":["Kepuasan meningkat; waktu pencarian menjadi ukuran","Fulfillment membaik; real-time berarti sinkronisasi","Pencarian lebih cepat; manfaat total belum terbukti","Biaya layanan turun; pembatalan menjadi biaya penjual","Akurasi meningkat; kecepatan pembaruan menjadi proksi"],"analysis":["Waktu adalah satu dimensi; pembatalan bisa menurunkan kepuasan dan hasil survei belum tersedia.","Tampilan segera tidak membuktikan kecocokan inventori atau keberhasilan memenuhi pesanan.","Ada bukti efisiensi pencarian dan efek buruk pembatalan, sehingga manfaat keseluruhan memerlukan ukuran lanjut.","Pihak yang menanggung dan besarnya biaya tidak diberikan; pemindahan biaya pun bukan bukti biaya total turun.","Kecepatan pembaruan berbeda dari kebenaran isi dan kasus justru menyebut stok sering keliru."],"answer":2,"type":"mc","pool":"exam","source":"Pola Q1-12 diperjelas; manfaat potensial vs hasil terukur."},{"id":"exam-6-5","chapter":6,"topic":"LBS dalam perjalanan","section":"s4","prompt":"Lima fitur aplikasi perjalanan berikut memakai teknologi digital. Mana yang secara eksplisit membutuhkan lokasi pengguna untuk fungsi yang disebut, bukan sekadar dapat dipakai saat bepergian?","reason":"LBS menggunakan lokasi sebagai input relevansi layanan. Tempat terdekat memerlukan posisi relatif pengguna/tempat. Fitur lain dapat digunakan dalam perjalanan tanpa memakai lokasi. Ini menghindari ketergantungan pada label kategori lama yang tidak tersedia.","options":["Menampilkan riwayat pembelian perlengkapan wisata","Mengirim pesan ke teman melalui daftar kontak","Menyarankan halte terdekat dari posisi saat ini","Menerjemahkan pesan teks yang dimasukkan pengguna","Menyimpan tiket yang dipilih ke folder perjalanan"],"analysis":["Riwayat transaksi dapat diakses tanpa lokasi.","Komunikasi tidak otomatis memakai koordinat pengguna.","Kedekatan dihitung relatif terhadap posisi pengguna.","Isi teks dapat diterjemahkan tanpa lokasi geografis.","Penyimpanan dokumen tidak mensyaratkan posisi sekarang."],"answer":2,"type":"mc","pool":"exam","source":"Pola Q1-14 diperbaiki agar fungsi LBS terdefinisi jelas."},{"id":"exam-6-6","chapter":6,"topic":"Kompleksitas mobile","section":"s7","prompt":"Pilot menggabungkan empat fungsi ke satu aplikasi. Jumlah perpindahan aplikasi turun, tetapi salah pilih menu naik. Kedua temuan konsisten dengan integrasi kanal yang belum menyederhanakan interaksi.","reason":"Perpindahan aplikasi dan beban navigasi merupakan ukuran berbeda. Integrasi dapat mengurangi perpindahan sekaligus menambah kepadatan pilihan. Nilai usability perlu diuji pada tugas dan kesalahan, bukan jumlah aplikasi saja.","options":["Benar","Salah"],"analysis":["Perpindahan aplikasi dan beban navigasi merupakan ukuran berbeda. Integrasi dapat mengurangi perpindahan sekaligus menambah kepadatan pilihan. Nilai usability perlu diuji pada tugas dan kesalahan, bukan jumlah aplikasi saja.","Menolak klaim ini tidak sesuai mekanisme kasus. Perpindahan aplikasi dan beban navigasi merupakan ukuran berbeda. Integrasi dapat mengurangi perpindahan sekaligus menambah kepadatan pilihan. Nilai usability perlu diuji pada tugas dan kesalahan, bukan jumlah aplikasi saja."],"answer":0,"type":"tf","pool":"exam","source":"Pola Q1-23; limitasi kompleksitas."},{"id":"exam-6-7","chapter":6,"topic":"Mapping dan navigation","section":"s5","prompt":"Aplikasi menghitung rute tujuan dan memberi instruksi belok. Karena hasilnya digambar di peta, fungsi dominan yang diuji adalah mapping, sedangkan navigation hanya berlaku ketika koordinat perangkat dilacak.","reason":"Mapping merepresentasikan informasi geografis, navigation menentukan rute dan petunjuk menuju tujuan, sedangkan tracking mengikuti posisi atau pergerakan. Tampilan peta tidak mengubah instruksi rute menjadi sekadar mapping; klaim juga mencampurkan navigation dengan tracking.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Mapping merepresentasikan informasi geografis, navigation menentukan rute dan petunjuk menuju tujuan, sedangkan tracking mengikuti posisi atau pergerakan. Tampilan peta tidak mengubah instruksi rute menjadi sekadar mapping; klaim juga mencampurkan navigation dengan tracking.","Mapping merepresentasikan informasi geografis, navigation menentukan rute dan petunjuk menuju tujuan, sedangkan tracking mengikuti posisi atau pergerakan. Tampilan peta tidak mengubah instruksi rute menjadi sekadar mapping; klaim juga mencampurkan navigation dengan tracking."],"answer":1,"type":"tf","pool":"exam","source":"Pola Q1-24 diperjelas; mapping vs navigation."},{"id":"exam-6-8","chapter":6,"topic":"Bandwidth","section":"s7","prompt":"Pada jaringan yang bandwidth-nya dinaikkan, ukuran berkas tetap dan waktu propagasi tidak berubah. Seluruh penurunan waktu transfer berkas itu dapat ditafsirkan sebagai hilangnya waktu propagasi.","reason":"Bandwidth memengaruhi berapa banyak data dapat ditransfer per waktu. Propagasi merupakan waktu perjalanan sinyal dan dinyatakan tetap; mengatribusikan perubahan transfer kepada hilangnya propagasi bertentangan dengan asumsi kasus.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Bandwidth memengaruhi berapa banyak data dapat ditransfer per waktu. Propagasi merupakan waktu perjalanan sinyal dan dinyatakan tetap; mengatribusikan perubahan transfer kepada hilangnya propagasi bertentangan dengan asumsi kasus.","Bandwidth memengaruhi berapa banyak data dapat ditransfer per waktu. Propagasi merupakan waktu perjalanan sinyal dan dinyatakan tetap; mengatribusikan perubahan transfer kepada hilangnya propagasi bertentangan dengan asumsi kasus."],"answer":1,"type":"tf","pool":"exam","source":"Pola Q1-25; kapasitas jaringan dan batas inferensi."},{"id":"exam-6-9","chapter":6,"topic":"IoT dan M2M","section":"s6","prompt":"Sensor dan aktuator yang bertukar data secara otomatis memberi contoh M2M; aplikasi IoT dapat memakai komunikasi tersebut bersama pengolahan data dan layanan pengguna.","reason":"M2M menyebut komunikasi antarmesin. IoT dapat menggabungkannya dalam arsitektur yang lebih luas. Pernyataan tidak menganggap keduanya identik atau bahwa komunikasi saja sudah melengkapi seluruh layanan.","options":["Benar","Salah"],"analysis":["M2M menyebut komunikasi antarmesin. IoT dapat menggabungkannya dalam arsitektur yang lebih luas. Pernyataan tidak menganggap keduanya identik atau bahwa komunikasi saja sudah melengkapi seluruh layanan.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Pola Q1-26; hubungan M2M–IoT."},{"id":"exam-6-10","chapter":6,"topic":"Context-aware tanpa lokasi","section":"s5","prompt":"Aplikasi memilih mode hemat data berdasarkan kualitas koneksi. Dalam context-aware computing, kondisi jaringan yang memengaruhi perilaku aplikasi termasuk konteks meskipun koordinat tidak dipakai.","reason":"Konteks meliputi informasi relevan tentang situasi pengguna, perangkat atau interaksi. Kondisi jaringan dapat memicu adaptasi yang relevan; location awareness merupakan salah satu bentuk, bukan batas seluruh konteks.","options":["Benar","Salah"],"analysis":["Konteks meliputi informasi relevan tentang situasi pengguna, perangkat atau interaksi. Kondisi jaringan dapat memicu adaptasi yang relevan; location awareness merupakan salah satu bentuk, bukan batas seluruh konteks.","Menolak klaim ini tidak sesuai mekanisme kasus. Konteks meliputi informasi relevan tentang situasi pengguna, perangkat atau interaksi. Kondisi jaringan dapat memicu adaptasi yang relevan; location awareness merupakan salah satu bentuk, bukan batas seluruh konteks."],"answer":0,"type":"tf","pool":"exam","source":"Pola Q1-29; Context Toolkit dan materi penghubung."},{"id":"exam-7-1","chapter":7,"topic":"Limitasi social commerce","section":"s4","prompt":"Platform memiliki konten pengguna yang beragam. Banyak ulasan sudah diverifikasi pembeliannya, tetapi rekomendasi produk masih tidak cocok bagi pengguna baru. Respons konseptual paling tepat adalah…","reason":"Verifikasi pembelian memperkuat satu aspek kredibilitas ulasan. Kecocokan rekomendasi adalah masalah lain yang melibatkan konteks, data pengguna serta model. Kuis lama tidak boleh dipakai untuk menolak relevansi masalah rekomendasi.","options":["Evaluasi kecocokan rekomendasi serta konteks pengguna","Perketat verifikasi transaksi sebagai perbaikan utama","Naikkan bobot popularitas pada semua pengguna baru","Tambahkan jumlah ulasan sebagai satu ukuran kecocokan","Utamakan ulasan terbaru tanpa memeriksa preferensi"],"analysis":["Verifikasi ulasan membantu keaslian sumber, bukan kecocokan bagi pengguna baru yang minim riwayat.","Dapat membantu trust, tetapi sebagian besar ulasan sudah terverifikasi dan masalahnya relevansi bagi pengguna baru.","Popularitas dapat menjadi baseline, tetapi tidak langsung menyelesaikan perbedaan kebutuhan pengguna baru.","Volume ulasan tidak menentukan apakah produk sesuai konteks seseorang.","Kebaruan informasi dapat membantu, tetapi tidak menggantikan kesesuaian kebutuhan."],"answer":0,"type":"mc","pool":"exam","source":"Pola Q1-15 dikritisi; kualitas UGC dan rekomendasi."},{"id":"exam-7-2","chapter":7,"topic":"Social shopping dan bukti manfaat","section":"s2","prompt":"Fitur wish list bersama menaikkan jumlah produk yang ditemukan pengguna. Conversion belum berubah dan biaya layanan meningkat. Kesimpulan mana paling sesuai bukti, tanpa menolak potensi fitur tersebut?","reason":"Discovery, conversion dan profit adalah hasil berbeda. Kasus mendukung perbaikan discovery, bukan peningkatan laba atau kepercayaan yang belum diukur. Evaluasi berikut dapat menelusuri jalur dari penemuan hingga transaksi.","options":["Discovery meningkat; hasil finansial perlu diuji lanjut","Laba meningkat karena lebih banyak produk ditemukan","Kepercayaan meningkat karena daftar dibuat bersama","Fitur gagal karena conversion belum berubah","Group buying terbentuk karena pengguna berbagi daftar"],"analysis":["Membatasi kesimpulan pada ukuran yang tersedia.","Mengabaikan conversion tetap dan tambahan biaya layanan.","Tidak ada ukuran kepercayaan atau bukti langsungnya.","Penilaian gagal memerlukan tujuan, waktu dan manfaat yang ditetapkan.","Berbagi pilihan belum berarti menggabungkan komitmen pembelian."],"answer":0,"type":"mc","pool":"exam","source":"Pola Q1-18; manfaat social shopping dan pengukuran."},{"id":"exam-7-3","chapter":7,"topic":"Social shopping aids","section":"s2","prompt":"Tim ingin memisahkan lima fungsi: ulasan dengan sponsor, insentif rujukan, penyimpanan tautan, pencocokan preferensi, dan demonstrasi live. Pasangan fungsi–mekanisme yang salah adalah…","reason":"Soal meminta pasangan yang tidak cocok, bukan menolak suatu fitur sebagai alat bantu selamanya. Sponsored review terkait hubungan sponsor; matching terkait kecocokan; referral terkait rujukan; bookmarking terkait tautan; livestream terkait demonstrasi langsung.","options":["Penyimpanan tautan — social bookmarking","Demonstrasi langsung — livestreaming feature","Insentif rujukan — social bookmarking","Ulasan bersponsor — sponsored review","Kecocokan preferensi — matching algorithm"],"analysis":["Pasangan tepat pada pengorganisasian rujukan.","Pasangan tepat pada penyajian/interaksi real-time.","Bookmarking menyimpan/membagikan rujukan, tidak mendefinisikan skema insentif referral.","Pasangan tepat pada hubungan konten dengan sponsor.","Pasangan tepat untuk menyarankan pilihan berdasarkan kesesuaian."],"answer":2,"type":"mc","pool":"exam","source":"Pola Q1-21 diperjelas; social shopping aids."},{"id":"exam-7-4","chapter":7,"topic":"Pendorong adopsi dan hasil","section":"s1","prompt":"Analisis industri mencatat pertumbuhan pengguna jejaring, tekanan kompetisi dan kebutuhan kolaborasi. Sesudah pilot, perusahaan juga menemukan kenaikan trust. Pernyataan metodologis terbaik adalah…","reason":"Driver adopsi dan hasil implementasi dapat berbeda, tetapi trust juga mungkin berperan pada keduanya. Kasus hanya menempatkan pengukuran trust setelah pilot; waktu pengukuran tidak membuktikan kausalitas atau melarangnya menjadi pendorong pada konteks lain.","options":["Gunakan kenaikan trust sebagai bukti ROI positif","Gunakan kebutuhan kolaborasi sebagai bukti trust naik","Pisahkan driver awal dan hasil; uji hubungan trust","Tetapkan trust sebagai driver awal dari hasil pilot","Tetapkan pertumbuhan jejaring sebagai akibat pilot"],"analysis":["Trust dapat memberi manfaat, tetapi ROI memerlukan manfaat yang dibandingkan dengan biaya pada horizon yang sama.","Kebutuhan adalah alasan tindakan, bukan pengukuran hasil kepercayaan sesudah implementasi.","Urutan kejadian membantu membedakan alasan adopsi dari hasil; hubungan kausal trust masih perlu diuji.","Hasil yang ditemukan sesudah pilot tidak cukup membuktikan alasan awal adopsi.","Pertumbuhan industri telah dicatat sebelum pilot, sehingga tidak dapat begitu saja diatribusikan pada pilot perusahaan."],"answer":2,"type":"mc","pool":"exam","source":"Pola Q1-28 diperjelas; driver vs outcome."},{"id":"exam-7-5","chapter":7,"topic":"Justifikasi Enterprise 2.0","section":"s7","prompt":"Direksi menolak perluasan jejaring internal karena 20.000 posting belum dapat dikaitkan dengan manfaat dibanding biaya. Integrasi dan antusiasme pengguna sudah memadai. Rancangan pilot berikut yang paling menjawab keberatan adalah…","reason":"Keberatan menyangkut bukti manfaat relatif terhadap biaya. Rancangan perlu baseline, ukuran hasil dan pembanding untuk menilai klaim. Aktivitas posting, fitur dan integrasi tidak menggantikan justifikasi investasi.","options":["Bandingkan kepuasan pengguna dan jumlah komunitas","Bandingkan waktu penyelesaian kasus dan total biaya","Bandingkan posting per pegawai dan pengguna aktif","Bandingkan jumlah koneksi dan kelengkapan profil","Bandingkan uptime sistem dan kecepatan pencarian"],"analysis":["Sinyal pengalaman berguna, tetapi belum membuktikan manfaat finansial dibanding investasi.","Dengan baseline serta kasus sebanding, waktu yang dihemat dapat dinilai terhadap biaya dan mutu hasil.","Mengukur adopsi/aktivitas yang sudah memadai, belum menjawab imbal balik terhadap biaya.","Mengukur jangkauan jejaring, tetapi nilai produktivitas atau biaya belum ditunjukkan.","Menguji kualitas teknis; perlu hubungan dengan hasil kerja serta total biaya untuk menjawab keberatan direksi."],"answer":1,"type":"mc","pool":"exam","source":"Pola Q1-30; hambatan ROI dan diagnosis masalah."},{"id":"exam-7-6","chapter":7,"topic":"Data management vs analytics","section":"s4","prompt":"Menghitung hubungan sentimen–retur terutama merupakan fungsi analytics; menyimpan hasilnya dalam repositori tidak mengubah tujuan analisis tersebut menjadi sekadar pengelolaan penyimpanan.","reason":"Tujuan kegiatan menentukan fungsi dominan. Hasil analisis memang perlu dikelola/disimpan, tetapi proses mencari hubungan tetap analitik. Satu workflow dapat menggabungkan beberapa fungsi yang berbeda.","options":["Benar","Salah"],"analysis":["Tujuan kegiatan menentukan fungsi dominan. Hasil analisis memang perlu dikelola/disimpan, tetapi proses mencari hubungan tetap analitik. Satu workflow dapat menggabungkan beberapa fungsi yang berbeda.","Pernyataan sesuai kondisi kasus. Menolaknya mengabaikan batas atau hubungan yang dinyatakan secara eksplisit."],"answer":0,"type":"tf","pool":"exam","source":"Pola Q1-03 diperjelas; pemisahan fungsi data."},{"id":"exam-7-7","chapter":7,"topic":"Landasan social commerce","section":"s1","prompt":"Tim menjelaskan social shopping melalui norma kelompok, preferensi individu, dan koordinasi daftar belanja bersama. Ketiga faktor itu berada sepenuhnya dalam perspektif perilaku konsumen sehingga analisis hubungan sosial dan kolaborasi tidak menambah penjelasan.","reason":"Preferensi individu berhubungan dengan perilaku konsumen; norma dan pengaruh kelompok memerlukan hubungan sosial; koordinasi daftar bersama memperlihatkan kolaborasi online. Perspektifnya dapat beririsan, tetapi memasukkan seluruhnya ke satu perspektif menghilangkan mekanisme pembeda.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Preferensi individu berhubungan dengan perilaku konsumen; norma dan pengaruh kelompok memerlukan hubungan sosial; koordinasi daftar bersama memperlihatkan kolaborasi online. Perspektifnya dapat beririsan, tetapi memasukkan seluruhnya ke satu perspektif menghilangkan mekanisme pembeda.","Preferensi individu berhubungan dengan perilaku konsumen; norma dan pengaruh kelompok memerlukan hubungan sosial; koordinasi daftar bersama memperlihatkan kolaborasi online. Perspektifnya dapat beririsan, tetapi memasukkan seluruhnya ke satu perspektif menghilangkan mekanisme pembeda."],"answer":1,"type":"tf","pool":"exam","source":"Pola Q1-05; fondasi konsep social commerce."},{"id":"exam-7-8","chapter":7,"topic":"Shopping guides","section":"s2","prompt":"Tim menggabungkan testimonial, video, dan studi kasus dari satu sponsor. Banyaknya format tersebut dapat dipakai sebagai bukti bahwa evaluasi telah menggunakan sumber yang independen.","reason":"Keragaman format bukan independensi asal informasi. Ketiganya berasal dari sponsor yang sama sehingga insentif serta bias dapat berkorelasi. Perlu memeriksa sumber, metode dan kesesuaian penggunaan, bukan menghitung format saja.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Keragaman format bukan independensi asal informasi. Ketiganya berasal dari sponsor yang sama sehingga insentif serta bias dapat berkorelasi. Perlu memeriksa sumber, metode dan kesesuaian penggunaan, bukan menghitung format saja.","Keragaman format bukan independensi asal informasi. Ketiganya berasal dari sponsor yang sama sehingga insentif serta bias dapat berkorelasi. Perlu memeriksa sumber, metode dan kesesuaian penggunaan, bukan menghitung format saja."],"answer":1,"type":"tf","pool":"exam","source":"Pola Q1-10; panduan social shopping."},{"id":"exam-7-9","chapter":7,"topic":"Group buying dan biaya total","section":"s3","prompt":"Pembelian kelompok memberi diskon Rp12.000 per unit dan memerlukan distribusi tambahan Rp15.000 per unit dibanding pembelian individual. Dengan komponen biaya lain sama, kelompok menghemat Rp3.000 per unit.","reason":"Perubahan biaya bersih = −Rp12.000 + Rp15.000 = +Rp3.000. Angkanya adalah tambahan biaya, bukan penghematan. Diskon pembelian tidak dapat dinilai terpisah dari biaya koordinasi atau distribusi yang ditimbulkannya.","options":["Benar","Salah"],"analysis":["Kesalahan klaimnya terletak pada hubungan konsep berikut. Perubahan biaya bersih = −Rp12.000 + Rp15.000 = +Rp3.000. Angkanya adalah tambahan biaya, bukan penghematan. Diskon pembelian tidak dapat dinilai terpisah dari biaya koordinasi atau distribusi yang ditimbulkannya.","Perubahan biaya bersih = −Rp12.000 + Rp15.000 = +Rp3.000. Angkanya adalah tambahan biaya, bukan penghematan. Diskon pembelian tidak dapat dinilai terpisah dari biaya koordinasi atau distribusi yang ditimbulkannya."],"answer":1,"type":"tf","pool":"exam","source":"Pola Q1-13; daya tawar dan keekonomian pembelian kelompok."},{"id":"exam-7-10","chapter":7,"topic":"Enterprise 2.0 dan tagging","section":"s5","prompt":"Pegawai memberi tag bebas, lalu kurator memetakan sinonim ke kategori resmi tanpa menghapus tag asal. Sistem ini menggabungkan folksonomy dengan taxonomy.","reason":"Tag pengguna membentuk klasifikasi partisipatif; kategori resmi memberi struktur terkelola. Pemetaan dapat mempertahankan kedua lapisan. Keberadaan taxonomy tidak dengan sendirinya menghapus kontribusi pengguna atau karakter Enterprise 2.0.","options":["Benar","Salah"],"analysis":["Tag pengguna membentuk klasifikasi partisipatif; kategori resmi memberi struktur terkelola. Pemetaan dapat mempertahankan kedua lapisan. Keberadaan taxonomy tidak dengan sendirinya menghapus kontribusi pengguna atau karakter Enterprise 2.0.","Menolak klaim ini tidak sesuai mekanisme kasus. Tag pengguna membentuk klasifikasi partisipatif; kategori resmi memberi struktur terkelola. Pemetaan dapat mempertahankan kedua lapisan. Keberadaan taxonomy tidak dengan sendirinya menghapus kontribusi pengguna atau karakter Enterprise 2.0."],"answer":0,"type":"tf","pool":"exam","source":"Pola Q1-22; taxonomy vs folksonomy."}];
